return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_DE','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-29T14:57:34+00:00','po-revision-date'=>'2026-07-05 20:35+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Mehrsprachiges Routing, vollständiges mehrsprachiges SEO (hreflang, Open Graph, Schema.org, Sitemap) und KI-Inhaltstools für WordPress. Spracherkennung, URL-Routing, Übersetzung, Inhaltserstellung und eine vollständige SEO-Schicht — kein Begleit-Plugin erforderlich.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Übersetzen','Lingua Forge — Quick Translate'=>'Lingua Forge — Schnelles Übersetzen','Informative'=>'Informativ','Persuasive'=>'Überzeugend','Storytelling'=>'Storytelling','Technical'=>'Technisch','Conversational'=>'Gesprächig','Translate missing'=>'Fehlende Übersetzung','%d comment translation created.'=>'%d Kommentarübersetzung erstellt.' . "\0" . '%d Kommentarübersetzungen erstellt.','%d pair could not be translated yet (e.g. a nested reply waiting on its parent, or a language currently in cooldown after repeated failures).'=>'%d Paare konnten noch nicht übersetzt werden (z. B. eine geschachtelte Antwort, die auf ihr übergeordnetes Element wartet, oder eine Sprache, die nach wiederholten Fehlern derzeit abgekühlt ist).' . "\0" . '%d Paare konnten noch nicht übersetzt werden (z. B. geschachtelte Antworten, die auf ihr übergeordnetes Element warten, oder eine Sprache, die nach wiederholten Fehlern derzeit abgekühlt ist).','Permission denied.'=>'Zugriff verweigert.','Cannot determine target language from slug.'=>'Ziel-Sprache kann aus dem Slug nicht bestimmt werden.','Invalid post type.'=>'Ungültiger Beitragstyp.','Invalid or primary language.'=>'Ungültige oder primäre Sprache.','Template not found or not stored in the database.'=>'Vorlage nicht gefunden oder nicht in der Datenbank gespeichert.','Template has no content.'=>'Vorlage hat keinen Inhalt.','No internal links found to update.'=>'Keine internen Links zum Aktualisieren gefunden.','%d link updated.'=>'%d Link aktualisiert.' . "\0" . '%d Links aktualisiert.','No language-specific template parts found to map.'=>'Keine sprachspezifischen Vorlage-Teile zum Abbilden gefunden.','No template part references needed updating.'=>'Keine Vorlage-Teile-Referenzen zum Aktualisieren erforderlich.','%d part reference updated.'=>'%d Teil-Referenz aktualisiert.' . "\0" . '%d Teil-Referenzen aktualisiert.','Invalid language.'=>'Ungültige Sprache.','Template part not found or not stored in the database.'=>'Vorlage-Teil nicht gefunden oder nicht in der Datenbank gespeichert.','Template part has no content.'=>'Vorlage-Teil hat keinen Inhalt.','No navigation references needed updating.'=>'Keine Navigationsreferenzen zum Aktualisieren erforderlich.','%d navigation reference updated.'=>'%d Navigationsreferenz aktualisiert.' . "\0" . '%d Navigationsreferenzen aktualisiert.','No AI provider configured.'=>'Kein KI-Anbieter konfiguriert.','Missing pattern name or language.'=>'Fehlender Mustername oder Sprache.','Pattern not found.'=>'Muster nicht gefunden.','Pattern has no content to translate.'=>'Muster hat keinen zu übersetzenden Inhalt.','AI provider returned an empty response.'=>'KI-Anbieter hat eine leere Antwort zurückgegeben.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muster übersetzt und gespeichert. Kopiere den Inhalt in deinen CPT-Beitrag über den Block-Editor Muster-Insertor oder nutze es als Ausgangspunkt für einen wiederverwendbaren Block.','%d template repaired.'=>'%d Vorlage repariert.' . "\0" . '%d Vorlagen repariert.','All template metadata is already up to date.'=>'Alle Vorlagen-Metadaten sind bereits aktuell.','Invalid template type.'=>'Ungültiger Vorlage-Typ.','Template "%s" already exists.'=>'Vorlage "%s" existiert bereits.','Fix Links'=>'Links reparieren','Fix Parts'=>'Teile reparieren','Re-create'=>'Neu erstellen','"%s" recreated.'=>'"%s" neu erstellt.','"%s" created.'=>'"%s" erstellt.','Invalid template part.'=>'Ungültiger Vorlage-Teil.','Template part "%s" already exists.'=>'Vorlage-Teil "%s" existiert bereits.','Fix Nav'=>'Navigation reparieren','"%1$s" recreated. %2$d template updated.'=>'"%1$s" neu erstellt. %2$d Template aktualisiert.' . "\0" . '"%1$s" neu erstellt. %2$d Templates aktualisiert.','"%1$s" created. %2$d template updated.'=>'"%1$s" erstellt. %2$d Vorlage aktualisiert.' . "\0" . '"%1$s" erstellt. %2$d Vorlagen aktualisiert.','Page'=>'Seite','Single'=>'Einzeln','Search'=>'Suche','Search Results'=>'Suchergebnisse','Archive'=>'Archiv','Front Page'=>'Startseite','Blog Home'=>'Blog-Startseite','Single: %s'=>'Einzeln: %s','Single %s'=>'Einzeln %s','Archive: %s'=>'Archiv: %s','%s Archive'=>'%s Archiv','No source content found to translate.'=>'Kein Quellinhalt zum Übersetzen gefunden.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Übersetzt. Überprüfe im Site Editor — interne Links, Navigations-URLs und Template-Slugs werden nicht automatisch aktualisiert.','Navigation not found.'=>'Navigation nicht gefunden.','Navigation has no content to translate.'=>'Navigation hat keinen Inhalt zum Übersetzen.','"%1$s %2$s" saved.'=>'"%1$s %2$s" gespeichert.','SEO Analysis'=>'SEO-Analyse','Profile'=>'Profil','Details ↗'=>'Details ↗','/ 100'=>'/ 100','Overall SEO score'=>'Gesamter SEO-Score','Metric'=>'Metrik','Finding'=>'Finden','Title'=>'Titel','Meta description'=>'Meta-Beschreibung','Word count'=>'Wortanzahl','Reading time'=>'Lesezeit','Headings'=>'Überschriften','Images'=>'Bilder','Links'=>'Links','AI Recommendations'=>'KI-Empfehlungen','Run AI Analysis'=>'KI-Analyse durchführen','Analyzing…'=>'Analysiere…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Konfiguriere einen KI-Anbieter in Einstellungen → API-Schlüssel, um KI-gestützte Empfehlungen zu aktivieren.','AI analysis failed. Please try again.'=>'KI-Analyse fehlgeschlagen. Bitte versuche es erneut.','Suggested title'=>'Vorgeschlagener Titel','Suggested meta description'=>'Vorgeschlagene Meta-Beschreibung','Loaded from cache.'=>'Geladen aus dem Cache.','↺ Refresh AI Analysis'=>'↺ KI-Analyse aktualisieren','Analyse…'=>'Analysieren…','Analysis request failed. Please try again.'=>'Analyseanfrage fehlgeschlagen. Bitte versuche es erneut.','No translation found — analyzed the source language version.'=>'Keine Übersetzung gefunden — die Quellversion wurde analysiert.','Translate page…'=>'Seite übersetzen…','Generate content…'=>'Inhalt generieren…','AI Behaviour Preset'=>'KI-Verhaltensvorgabe','Custom'=>'Benutzerdefiniert','Global default (%s)'=>'Globale Standardeinstellung (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Site-weite benutzerdefinierte Anweisungen (Einstellungen → Verhalten) werden immer an jede Anfrage angehängt, unabhängig von dieser Auswahl.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Überschreibt die KI-Voreinstellung für Übersetzung und Inhaltserstellung auf dieser Seite. Alle anderen Funktionen verwenden immer die globale Voreinstellung.','Close'=>'Schließen','From'=>'Von','Retranslate'=>'Erneut übersetzen','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Übersetzen Sie jede andere Sprachversion dieses Beitrags neu. Erstellt fehlende Versionen und überschreibt existierende — einschließlich der Primärsprache, falls dieser Beitrag eine Übersetzung ist.','Sync'=>'Sync','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Weisen Sie jeder existierenden Übersetzung dieses Beitrags das korrekte sprachspezifische Template zu. Kein KI-Aufruf und keine Inhaltsänderungen — kostenlos und sicher, jederzeit ausführbar.','Template Sync — reassign templates for every translation'=>'Template Sync — Templates für jede Übersetzung neu zuweisen','TS'=>'TS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Letzter regelbasierter SEO-Score. Führe die Analyse in Einstellungen → SEO → Analyse durch, um zu aktualisieren.','Translating…'=>'Übersetze…','Retranslating…'=>'Erneut übersetzen…','Syncing…'=>'Synchronisierung läuft…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Dies übersetzt jede andere Sprachversion dieses Beitrags neu von diesem aus — erstellt fehlende Versionen und überschreibt existierende (einschließlich der Primärsprache, falls dieser Beitrag eine Übersetzung ist). Dies kann nicht rückgängig gemacht werden. Fortfahren?','Syncing templates…'=>'Templates werden synchronisiert…','✓ Done'=>'✓ Fertig','Error'=>'Fehler','Navigation posts are translated via the Router tab, not this button.'=>'Navigation-Posts werden über den Router-Tab übersetzt, nicht über diese Schaltfläche.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Das Erstellen von Übersetzungen für den Beitragstyp "%s" erfordert eine aktive Integration. Bitte stelle sicher, dass die erforderliche Integration installiert und aktiviert ist.','No %s version found in this translation group.'=>'Keine %s-Version in dieser Übersetzungsgruppe gefunden.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Sync von einem WooCommerce-Produkt in einer Sekundärsprache ist standardmäßig deaktiviert, da es das primäre Produkt überschreiben würde. Aktivieren Sie es in Einstellungen → Verhalten → WooCommerce, wenn Sie möchten, dass eine Übersetzung zur neuen Quelle werden kann.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Sync von einem Beitrag in einer Sekundärsprache ist standardmäßig deaktiviert, da es den primären Beitrag überschreiben würde. Aktivieren Sie es in Einstellungen → Verhalten → Sync, wenn Sie möchten, dass eine Übersetzung zur neuen Quelle werden kann.','Skipped — you do not have permission to edit the existing translation.'=>'Übersprungen — Sie haben keine Berechtigung, die existierende Übersetzung zu bearbeiten.','Creating translations for post type "%s" requires an active integration.'=>'Das Erstellen von Übersetzungen für den Beitragstyp "%s" erfordert eine aktive Integration.','Template Sync can only be run from the primary/source-language post.'=>'Template Sync kann nur vom primären/Quellsprachen-Beitrag ausgeführt werden.','Skipped — you do not have permission to edit this translation.'=>'Übersprungen — Sie haben keine Berechtigung, diese Übersetzung zu bearbeiten.','Translation Caching'=>'Übersetzungscaching','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge verwendet zwei unabhängige Cache-Schichten, um redundante KI-API-Aufrufe zu vermeiden. Verwende die untenstehenden Tabs, um jede zu inspizieren und zu verwalten.','API Response Cache'=>'API-Antwort-Cache','Translation Memory'=>'Übersetzungsspeicher','(disabled)'=>'deaktiviert','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Cache pro Beitrag für KI-generierte Übersetzungen, Meta-Beschreibungen, Auszüge und Inhalte. Einträge werden automatisch invalidiert, wenn sich der Inhalt oder der KI-Anbieter/-Modell ändert.','Enable API response caching'=>'API-Antwort-Cache aktivieren','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Der API-Antwort-Cache speichert das rohe Ergebnis jeder KI-Anfrage — Übersetzung, Meta-Beschreibung, Auszug und Inhaltserstellung — basierend auf einem Hash der Eingaben (Inhalt, Sprachpaar, Anbieter, Modell). Deaktiviere ihn während der Prompt-Feinabstimmung oder wenn jede Anfrage den KI-Anbieter erreichen soll. Das Deaktivieren löscht keine zwischengespeicherten Einträge — das erneute Aktivieren stellt sie wieder her.','Save'=>'Speichern','Cached API responses'=>'Zwischengespeicherte API-Antworten','API calls saved by cache'=>'API-Aufrufe, die durch den Cache gespeichert wurden','(avg %.1f hits/entry)'=>'(Durchschnitt %.1f Treffer/Eintrag)','Oldest cached response'=>'Älteste zwischengespeicherte Antwort','Most recent cached response'=>'Kürzlich zwischengespeicherte Antwort','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Alle zwischengespeicherten KI-Ergebnisse löschen? Zukünftige Anfragen lösen neue API-Aufrufe aus, bis der Cache neu aufgebaut ist.','Clear API Response Cache'=>'API-Antwort-Cache leeren','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Block-Übersetzungscache, der über Beiträge hinweg geteilt wird. Wenn aktiviert, werden identische Blöcke (gleiche Markup, Sprachpaar und Glossar) aus dem Speicher bedient, anstatt die KI erneut aufzurufen. Glossar-Änderungen und Änderungen am Compliance-Preset invalidieren automatisch betroffene zwischengespeicherte Übersetzungen.','Enable block-level translation cache reuse across posts'=>'Blockebenen-Übersetzungscache-Wiederverwendung über Beiträge hinweg aktivieren','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Derzeit übersprungen für Beiträge, die Block-Kommentar-Attribut-Platzhalter verwenden (wp:details Zusammenfassungsfelder usw.) — sie fallen auf den bestehenden Einzel-Aufruf-Übersetzungsweg zurück.','Cached block translations'=>'Zwischengespeicherte Blockübersetzungen','Block translation reuses'=>'Block-Übersetzungs-Wiederverwendung','(avg %.1f hits/block)'=>'(ø %.1f Treffer/Block)','Oldest cached block'=>'Ältester zwischengespeicherter Block','Most recent cached block'=>'Kürzlich zwischengespeicherter Block','Approximate size'=>'Ungefähre Größe','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Gesamten Übersetzungsspeicher löschen? Zukünftige Übersetzungen bauen den Cache beim Ausführen neu auf.','Clear Translation Memory'=>'Übersetzungsspeicher löschen','API Response Cache setting saved.'=>'API-Antwort-Cache-Einstellung gespeichert.','Translation Memory setting saved.'=>'Einstellung für Übersetzungsspeicher gespeichert.','AI cache cleared. %d entry was removed.'=>'KI-Cache gelöscht. %d Eintrag wurde entfernt.' . "\0" . 'KI-Cache gelöscht. %d Einträge wurden entfernt.','Translation Memory cleared. %d cached block was removed.'=>'Übersetzungsspeicher gelöscht. %d zwischengespeicherter Block wurde entfernt.' . "\0" . 'Übersetzungsspeicher gelöscht. %d zwischengespeicherte Blöcke wurden entfernt.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge ist eine vollständige mehrsprachige SEO-Lösung. Es ist kein zusätzliches SEO-Plugin erforderlich.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Wenn du ein allgemeines SEO-Plugin installiert hast, zeigt dieses Panel, wie LF sich anpasst, um doppelte Ausgaben zu vermeiden. Das Ziel ist Kollisionsvermeidung — nicht Zusammenarbeit. LF bietet immer die mehrsprachige SEO-Schicht (hreflang, og:locale, inLanguage schema), die Kenntnisse über LF\'s Sprachrouting-Konfiguration erfordert, um korrekt zu produzieren.','Installed SEO plugins'=>'Installierte SEO-Plugins','Plugin'=>'Plugin','Status'=>'Status','✓ Active'=>'✓ Aktiv','— Not detected'=>'— Nicht erkannt','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Keine konfliktverursachenden SEO-Plugins erkannt. Lingua Forge übernimmt alle SEO-Ausgaben eigenständig.','What LF provides — and collision avoidance'=>'Was LF bietet — und Kollisionsvermeidung','Feature'=>'Funktion','LF provides'=>'LF bietet','When another SEO plugin is installed'=>'Wenn ein anderes SEO-Plugin installiert ist','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Deaktiviert (durch Einstellung)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF-Ausgaben — Plugin hreflang unterdrückt','✓ LF outputs'=>'✓ LF-Ausgaben','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF gibt für jede konfigurierte Sprache, einschließlich x-default, genaue hreflang-Tags aus. Allgemeine SEO-Plugins haben keinen Zugriff auf deine LF-Routing-Konfiguration und würden hreflang basierend auf falschen URL-Annahmen erzeugen. LF unterdrückt deren Ausgabe über einen Filter, um Kollisionen zu vermeiden.','Suppressed: %s.'=>'Unterdrückt: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Deaktiviert (Modus-Einstellung)','→ Locale tags only — deferring base OG to plugin'=>'→ Nur Locale-Tags — Standard OG an Plugin delegieren','→ Locale tags only (manual setting)'=>'→ Nur Locale-Tags (manuelle Einstellung)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF-Ausgaben vollständige OG + Twitter Cards','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF fügt immer og:locale und og:locale:alternate hinzu — die mehrsprachigen OG-Signale, die kein allgemeines SEO-Plugin korrekt produzieren kann. Für das Basis-OG-Set (og:title, og:description, og:image) gibt LF es aus, wenn kein anderes Plugin vorhanden ist. Wenn ein SEO-Plugin installiert ist, überspringt LF das Basis-Set, um doppelte Tags zu vermeiden — nicht weil das Plugin "besser" ist, sondern weil Duplikate keinen Wert haben.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— An Plugin delegiert','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF-Ausgaben Artikel / WebPage / WebSite','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF gibt mehrsprachiges JSON-LD mit inLanguage-Annotationen aus, die an seine Sprachrouting-Konfiguration gebunden sind. Wenn ein SEO-Plugin installiert ist, deaktiviert LF sein eigenes Schema vollständig: Doppelte JSON-LD-Grafen führen zu Validierungsfehlern, und es gibt keinen sauberen Weg, eine bestehende Grafik zu ergänzen.','XML Sitemap'=>'XML-Sitemap','✓ Active at /lf-sitemap.xml'=>'✓ Aktiv bei /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF generiert seine eigene Sitemap mit xhtml:link Alternates für alle Übersetzungsgruppen. Wenn ein SEO-Plugin installiert ist, erstellt es eine separate Sitemap — beide koexistieren unabhängig. Reiche beide bei Google Search Console ein: die Sitemap des SEO-Plugins für die Inhaltsentdeckung, die LF-Sitemap für Sprachbeziehungs-Signale.','Canonical tag'=>'Kanonische Tag','✓ WP canonical replaced (self-referencing)'=>'✓ WP-Kanonisch ersetzt (selbstreferenzierend)','WP core canonical active (hreflang disabled)'=>'WP-Kernkanonisch aktiv (hreflang deaktiviert)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF entfernt den WordPress-Kanonischen Tag und ersetzt ihn durch einen selbstreferenzierenden Kanonischen Link, der auf die korrekte sprachpräfixierte URL zeigt. Wenn ein Drittanbieter-SEO-Plugin (Yoast, Rank Math, AIOSEO, SEOPress) aktiv ist, überlässt LF die Kanonische Verwaltung vollständig diesem Plugin.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','The lf-social-share mu-plugin is active.'=>'Das lf-social-share Mu-Plugin ist aktiv.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Die integrierten Social Share- und Open Graph-Module von Lingua Forge decken alle Funktionen ab, die das mu-Plugin bietet, plus mehrsprachige og:locale-Unterstützung. Du kannst das mu-Plugin sicher deaktivieren.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card-Tags: werden vom LF-Open Graph-Modul (SEO → Open Graph & Twitter Cards) verwaltet','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Social Icons Block teilen: URLs: verwaltet durch LF\'s integrierten Social Share (SEO → Social Share)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'Kopieren/native/auto JS-Aktionen: werden von LF\'s social-share.js verarbeitet','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Solange aktiv, verwaltet das Mu-Plugin die Basis OG-Sätze und LF gibt nur Locale-Tags aus (Automodus). Das Entfernen schaltet LF automatisch auf den vollen OG-Modus um.','Debug Files'=>'Debug-Dateien','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wenn das Debug-Logging aktiviert ist (über den Schalter unten oder durch die Definition von LINGUAFORGE_AI_DEBUG in wp-config.php), schreiben die Übersetzungs- und FSE-Template-Übersetzungsfunktionen ihre rohen AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte. Nutze diesen Abschnitt, um diese Ausgabe zu überwachen und sie zu löschen, sobald du hast, was du brauchst — die Dateien können bei großen Seiten schnell wachsen. Konfiguriere das Zielverzeichnis über den linguaforge_debug_dir-Filter.','Debug files cleared. %d file was removed.'=>'Debug-Datei gelöscht. %d Datei wurde entfernt.' . "\0" . 'Debug-Dateien gelöscht. %d Dateien wurden entfernt.','Debug logging enabled.'=>'Debug-Logging aktiviert.','Debug logging disabled.'=>'Debug-Logging deaktiviert.','Debug logging'=>'Debug-Logging','Write AI prompts and responses to disk for troubleshooting'=>'AI-Aufforderungen und Antworten zur Fehlerbehebung auf die Festplatte schreiben','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen EIN durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Erzwungen AUS durch die Konstante LINGUAFORGE_AI_DEBUG in wp-config.php. Entferne diese Zeile, um diesen Schalter von hier aus zu steuern.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dateien landen im unten stehenden Verzeichnis. Nützlich zur Diagnose von Übersetzungsproblemen — schalte es aus, sobald du hast, was du brauchst, damit die Dateien sich nicht anhäufen. Du kannst dies auch in wp-config.php erzwingen mit `define( \'LINGUAFORGE_AI_DEBUG\', true );`, was den Schalter überschreibt.','Currently:'=>'Derzeit:','✓ Enabled'=>'✓ Aktiviert','✗ Disabled'=>'✗ Deaktiviert','Directory'=>'Verzeichnis','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Mit linguaforge_debug_dir filtern, um Debug-Ausgaben an einen nicht-öffentlichen Ort umzuleiten.','Files'=>'Dateien','.txt file(s) in the directory'=>'.txt-Datei(en) im Verzeichnis','Save Debug Setting'=>'Debug-Einstellung speichern','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Alle .txt-Dateien im Debug-Verzeichnis löschen? Das Verzeichnis selbst bleibt erhalten, damit zukünftige Debug-Schreibvorgänge weiterhin sauber landen.','Clear Debug Files'=>'Debug-Dateien löschen','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge gibt <link rel="alternate" hreflang>-Tags für jede konfigurierte Sprache auf jeder Seite aus, einschließlich x-default, das auf die Ausgangssprache verweist. Dies ist das wichtigste mehrsprachige SEO-Signal für Google und andere Suchmaschinen — kein zusätzliches SEO-Plugin ist erforderlich.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Wenn Yoast SEO, Rank Math, All in One SEO oder SEOPress aktiv sind, unterdrückt Lingua Forge deren hreflang-Ausgabe automatisch über einen Filter. Allgemeine SEO-Plugins erzeugen hreflang basierend auf einer einsprachigen URL-Struktur und können deine mehrsprachige Routing-Konfiguration nicht berücksichtigen; LF\'s Ausgabe ist immer korrekt.','Hreflang settings saved.'=>'Hreflang-Einstellungen gespeichert.','Hreflang output'=>'Hreflang-Ausgabe','Output hreflang tags in wp_head'=>'Ausgabe von hreflang-Tags in wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Nur für headless Seiten oder vollständig benutzerdefinierte hreflang-Implementierungen deaktivieren. Wenn deaktiviert, entfernt LF nicht mehr den WordPress-Kanonischen Tag und unterdrückt nicht mehr die SEO-Plugin hreflang-Ausgabe.','Current status'=>'Aktueller Status','✓ Hreflang active'=>'✓ Hreflang aktiv','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF gibt hreflang-Tags aus und ersetzt das WordPress-Core-Canonical durch ein selbstreferenzierendes Canonical für jede Sprachversion.','LF is suppressing hreflang output from: %s'=>'LF unterdrückt hreflang-Ausgabe von: %s','Save Hreflang Settings'=>'Hreflang-Einstellungen speichern','Language Overrides'=>'Sprachüberschreibungen','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Kompilierte .mo-Dateien hochladen, um Strings von Drittanbieter-Plugins für bestimmte Sprachen zu überschreiben – zum Beispiel eine benutzerdefinierte VikBooking-Übersetzung, die "Apartment" anstelle von "Zimmer" verwendet. Dateien müssen dem WordPress-Namensschema folgen: {textdomain}-{locale}.mo (z.B. vikbooking-ca.mo). Sie werden im Upload-Ordner gespeichert und überleben Plugin-Updates.','Override file uploaded successfully.'=>'Überschreibungsdatei erfolgreich hochgeladen.','Override file deleted.'=>'Überschreibungsdatei gelöscht.','No file was selected.'=>'Keine Datei ausgewählt.','Only .mo files are accepted.'=>'Nur .mo-Dateien werden akzeptiert.','The upload failed — please try again.'=>'Der Upload ist fehlgeschlagen – bitte versuche es erneut.','Could not save the file. Check that the uploads folder is writable.'=>'Datei konnte nicht gespeichert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Invalid filename.'=>'Ungültiger Dateiname.','Security check failed — file path is not permitted.'=>'Sicherheitsüberprüfung fehlgeschlagen – Dateipfad ist nicht erlaubt.','An unknown error occurred.'=>'Ein unbekannter Fehler ist aufgetreten.','Text domain / locale'=>'Textdomain / Sprache','Size'=>'Größe','Delete all files for this override (both .mo and .po)?'=>'Alle Dateien für diese Überschreibung löschen (sowohl .mo- als auch .po-Dateien)?','Delete'=>'Löschen','No override files uploaded yet.'=>'Noch keine Überschreibungsdateien hochgeladen.','Upload .mo file'=>'.mo-Datei hochladen','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akzeptiert nur kompilierte .mo-Dateien. Der Dateiname muss dem Muster {textdomain}-{locale}.mo folgen. Das Hochladen einer Datei mit demselben Namen wie eine bestehende ersetzt sie.','Upload Override'=>'Überschreibung hochladen','Loco Translate — Copy to Safe Storage'=>'Loco Translate – In sicheren Speicher kopieren','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate speichert seine benutzerdefinierten Übersetzungen im Verzeichnis wp-content/languages/loco/ – ein Ort, der bei einem WP-Kern-Update, Plugin-Neuinstallation oder bei Entfernung von Loco Translate still gelöscht werden kann. Das Kopieren der Dateien hier verschiebt sie in das Lingua Forge i18n-overrides-Verzeichnis, das all diesen Ereignissen standhält und bei jeder Anfrage automatisch geladen wird.','File copied to safe storage successfully.'=>'Datei erfolgreich in sicheren Speicher kopiert.','Source file not found.'=>'Quelldatei nicht gefunden.','Could not copy the file. Check that the uploads folder is writable.'=>'Datei konnte nicht kopiert werden. Überprüfe, ob der Upload-Ordner beschreibbar ist.','Invalid file reference.'=>'Ungültige Dateireferenz.','Type'=>'Typ','✓ In safe storage'=>'✓ Im sicheren Speicher','Copy to safe storage'=>'In sicheren Speicher kopieren','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Noch keine benutzerdefinierten Loco Translate-Dateien gefunden. Sie erscheinen hier, sobald du eine Übersetzung in Loco Translate speicherst.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge gibt Open Graph- und Twitter Card-Meta-Tags aus, damit geteilte URLs die richtige Sprache, Titel, Beschreibung und Bild auf sozialen Plattformen anzeigen.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Im Gegensatz zu hreflang — wo LF immer andere Plugins überschreibt, weil sie deine mehrsprachige Konfiguration nicht kennen — ist Open Graph anders: Yoast, Rank Math und ähnliche Plugins liefern bereits korrekte OG-Tags für deine Inhalte. Das Duplizieren bringt keinen Mehrwert. Im Automodus erkennt LF aktive SEO-Plugins und fügt nur das hinzu, was sie nicht bereitstellen: og:locale (aktuelle Sprache) und og:locale:alternate (alle anderen konfigurierten Sprachen).','Open Graph settings saved.'=>'Open Graph-Einstellungen gespeichert.','Open Graph output'=>'Open Graph-Ausgabe','Output Open Graph tags in wp_head'=>'Ausgabe von Open Graph-Tags in wp_head','Output mode'=>'Ausgabemodus','Auto (recommended)'=>'Automatisch (empfohlen)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Erkenne aktive SEO-Plugins (Yoast, Rank Math usw.) zur Laufzeit. Gib nur og:locale + og:locale:alternate aus, wenn ein anderes Plugin bereits das vollständige OG-Set ausgibt; gib das vollständige Set aus, wenn kein Plugin erkannt wird.','Locale only'=>'Nur Locale','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Immer nur og:locale und og:locale:alternate ausgeben. Verwende, wenn ein anderes Plugin oder Theme den vollständigen OG-Set verwaltet.','Full'=>'Vollständig','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Immer das vollständige OG + Twitter Card-Set ausgeben, unabhängig von anderen Plugins. Nur verwenden, wenn kein anderes Plugin OG-Tags ausgibt.','Disabled'=>'Deaktiviert','Do not output any OG tags.'=>'Keine OG-Tags ausgeben.','Default OG image'=>'Standard OG-Bild','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Fallback-Bild-URL, die verwendet wird, wenn eine Seite kein hervorgehobenes Bild, Logo oder Icon hat. Wird in sozialen Vorschauen für Archive, den Blog-Index und jede einzelne Seite ohne Thumbnail angezeigt.','— Disabled'=>'— Deaktiviert','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktiv — nur Locale-Tags (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktiv — vollständige OG + Twitter Cards','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin erkannt. LF überträgt das Basis-OG-Set an das mu-plugin und gibt nur og:locale + og:locale:alternate aus. Du kannst das mu-plugin deaktivieren — LF\'s integrierte Social Share (SEO → Social Share Tab) und Open Graph decken die gleiche Funktionalität ab.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO-Plugin(s) erkannt: %s. LF gibt nur og:locale und og:locale:alternate aus; das erkannte Plugin verarbeitet das vollständige OG-Set.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Kein externes OG-Plugin erkannt. LF gibt das vollständige OG + Twitter Card-Set aus.','Save Open Graph Settings'=>'Open Graph-Einstellungen speichern','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge gibt Schema.org JSON-LD strukturierte Daten aus, damit Suchmaschinen den Inhaltstyp, die Sprache und Metadaten verstehen. Dies ist der primäre Weg, um inLanguage-Annotationen für mehrsprachige Inhalte an Google und andere Crawler zu kommunizieren.','Schema output deferred.'=>'Schema-Ausgabe verzögert.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s ist aktiv und gibt bereits Schema.org JSON-LD aus. Lingua Forge hat die eigene Schema-Ausgabe deaktiviert, um Konflikte zu vermeiden. Im Gegensatz zu Open Graph — wo LF og:locale zusätzlich zu einem anderen Plugin hinzufügt — kann Schema nicht sauber ergänzt werden: doppelte oder überlappende JSON-LD-Grafen führen zu Validierungsfehlern. Deaktiviere die Schema-Ausgabe im erkannten Plugin, wenn LF die strukturierten Daten verwalten soll.','Schema.org settings saved.'=>'Schema.org-Einstellungen gespeichert.','Schema.org output'=>'Schema.org-Ausgabe','Output Schema.org JSON-LD in wp_head'=>'Ausgabe Schema.org JSON-LD im wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Gesperrt — ein konfliktverursachendes SEO-Plugin ist aktiv. Siehe die oben stehende Mitteilung.','Article / WebPage'=>'Artikel / Webseite','Output Article or WebPage schema on singular posts and pages'=>'Ausgabe von Artikel- oder WebPage-Schema auf einzelnen Beiträgen und Seiten','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blogbeiträge verwenden Artikel; alle anderen Beitragstypen und Seiten verwenden Webseite. Enthält Überschrift, Beschreibung, inSprache, URL, Veröffentlichungsdatum, Änderungsdatum, Bild und Verlag.','WebSite'=>'Webseite','Output WebSite schema on the front page and blog index'=>'Ausgabe des WebSite-Schemas auf der Startseite und im Blog-Index','Includes site name, url, and inLanguage.'=>'Enthält Seitenname, URL und inLanguage.','Product'=>'Produkt','Output Product schema on WooCommerce product pages'=>'Ausgabe von Product-Schema auf WooCommerce-Produktseiten','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Enthält Name, Beschreibung, inLanguage, URL, Bild und ein Angebot mit Preis, Währung und Verfügbarkeit. Preis und Verfügbarkeit stammen vom Produkt in der Quellsprache (gemeinsames Lager).','Currently emitting'=>'Derzeit wird ausgegeben','Article / WebPage — all singular posts and pages'=>'Artikel / Webseite — alle einzelnen Beiträge und Seiten','WebSite — front page / blog index'=>'Webseite — Startseite / Blog-Index','Product — WooCommerce product pages'=>'Produkt — WooCommerce-Produktseiten','Nothing — all types disabled'=>'Nichts — alle Typen deaktiviert','Save Schema.org Settings'=>'Schema.org-Einstellungen speichern','Blog / Editorial'=>'Blog / Redaktion','Product / eCommerce'=>'Produkt / E-Commerce','Landing / Short-form'=>'Landing / Kurzform','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtern nach Sprache und Beitragstyp, durchsuchen deiner Inhalte und auf beliebigem Element Analyse klicken, um eine regelbasierte SEO-Prüfung durchzuführen — Titel-Länge, Meta-Beschreibung, Wortzahl, Überschriftenstruktur, Bild-Alt-Abdeckung und interne Links.','Treat H2 as H1 equivalent'=>'H2 als H1-Äquivalent behandeln','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Aktiviere, wenn dein Theme den Beitragstitel als H2 anstelle von H1 rendert (häufig bei einigen Block-Themes). Der Analyzer holt die gerenderte Seite und, falls kein H1, aber ein H2 gefunden wird, hebt er das erste H2 für die Bewertung auf H1 an.','Save analysis settings'=>'Analyse-Einstellungen speichern','Per-Post Analysis'=>'Pro-Post-Analyse','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Wähle einen Beitrag aus und führe eine detaillierte SEO-Prüfung durch, um die Ergebnisse pro Metrik und eine Punktzahl für dieses spezielle Element zu sehen.','Language'=>'Sprache','source'=>'Quelle','All types'=>'Alle Typen','Load content'=>'Inhalt laden','Batch Analysis'=>'Batch-Analyse','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Führe eine vollständige SEO-Prüfung aller veröffentlichten Beiträge für eine oder alle aktiven Sprachen durch. Die Ergebnisse werden pro Beitrag gespeichert und in den Badge der Sprachspalte in der Beitragsliste angezeigt.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce-Systemseiten (Shop, Warenkorb, Kasse, Mein Konto) sind ausgeschlossen — ihr Inhalt wird von WooCommerce verwaltet und kann nicht durch SEO-Änderungen verbessert werden.','Post type'=>'Post-Typ','Default profile'=>'Standardprofil','— Auto-detect —'=>'— Automatisch erkennen —','Analyse all languages'=>'Alle Sprachen analysieren','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Auto-Erkennung weist zu: WooCommerce-Produkte → Produktprofil; die statische Startseite → Landing-Profil; alles andere → Blog-Profil. Wähle ein spezielles Profil, um dies für alle Beiträge zu überschreiben.','%d post'=>'%d Beitrag' . "\0" . '%d Beiträge','Last run: %s ago'=>'Letzter Lauf: %s vor','Never run'=>'Niemals laufen','avg'=>'durchschnittlich','(partial)'=>'(teilweise)','Analyse'=>'Analysieren','(no title) #%d'=>'(kein Titel) #%d','Invalid post ID.'=>'Ungültige Beitrag-ID.','Post not found or not published.'=>'Beitrag nicht gefunden oder veröffentlicht.','~%d min read'=>'~%d Min gelesen' . "\0" . '~%d Min gelesen','No title set.'=>'Kein Titel gesetzt.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Titel ist %1$d Zeichen — kann in SERPs gekürzt werden (angestrebt unter %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Der Titel hat nur %d Zeichen — streben Sie mindestens 10 Zeichen an.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Ein-Wort-Titel (%d Zeichen) — das Hinzufügen eines zweiten Wortes verbessert die Klarheit und Keyword-Abdeckung.','%1$d chars, %2$d words — good title.'=>'%1$d Zeichen, %2$d Wörter — guter Titel.','Using LF AI meta description.'=>'Verwendung der LF KI-Meta-Beschreibung.','No LF meta description set — using excerpt/content.'=>'Keine LF-Meta-Beschreibung gesetzt — Verwendung von Auszug/Inhalt.','No meta description found. Generate one via the AI meta description feature.'=>'Keine Meta-Beschreibung gefunden. Erstelle eine mit der AI-Meta-Beschreibungsfunktion.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d Zeichen — zu kurz (angestrebt: %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d Zeichen — wahrscheinlich in den SERPs abgeschnitten (halte es unter %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d Zeichen — gut, leicht über dem idealen %2$d, aber innerhalb des akzeptierten %3$d-Zeichenbereichs. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d Zeichen — ideale Länge. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d Wörter — sehr dünner Inhalt. Erwägen Sie, auf mindestens %2$d Wörter zu erweitern.','%1$d words — below recommended minimum of %2$d.'=>'%1$d Wörter — unter dem empfohlenen Minimum von %2$d.','%d words.'=>'%d Wörter.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-als-H1-Modus aktiviert — Titel wird als H1-Äquivalent gezählt. (Überschriften-Tags konnten auf der gerenderten Seite nicht erkannt werden; überprüfe, ob dein Theme den Titel korrekt ausgibt.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Kein H1 gefunden. In der Regel ist der Beitragstitel das H1 — überprüfe, ob dein Theme es ausgibt.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1-Tags gefunden — eine Seite sollte genau ein H1 haben.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — kein H2, aber %d H3-Unterüberschrift(en) gefunden (z.B. Akkordeon/Details-Header). Struktur ist akzeptabel.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — kurzer Inhalt (%d Absatz(e)), Unterüberschriften sind nicht erforderlich.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — keine H2-Unterüberschriften (akzeptabel für diesen Inhaltstyp).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — keine H2- oder H3-Unterüberschriften gefunden. Das Hinzufügen von H2s verbessert die Struktur.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Keine Bilder im Inhalt gefunden.','%1$d of %2$d image(s) missing alt text.'=>'%1$d von %2$d Bildern fehlen Alt-Text.','%d image(s), all have alt text.'=>'%d Bild(er), alle haben Alt-Text.','No links found. Internal links improve crawlability and user navigation.'=>'Keine Links gefunden. Interne Links verbessern die Crawlability und die Navigation der Nutzer.','No links found.'=>'Keine Links gefunden.','%d external link(s), no internal links. Add internal links to related content.'=>'%d externe Links, keine internen Links. Füge interne Links zu verwandten Inhalten hinzu.','%d external link(s), no internal links.'=>'%d externe Links, keine internen Links.','%1$d internal, %2$d external.'=>'%1$d intern, %2$d extern.','Post not found.'=>'Beitrag nicht gefunden.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Kein KI-Anbieter konfiguriert. Füge einen API-Schlüssel in Einstellungen → API-Schlüssel hinzu.','No response from AI provider. Check your API key and try again.'=>'Keine Antwort vom KI-Anbieter. Überprüfe deinen API-Schlüssel und versuche es erneut.','AI returned an unexpected response format. Please try again.'=>'KI lieferte ein unerwartetes Antwortformat. Bitte versuche es erneut.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge generiert eine spezielle XML-Sitemap unter /lf-sitemap.xml, die Sprach-Alternativlinks für alle übersetzten Inhalte hinzufügt. Diese Sitemap ergänzt die WordPress-Kerndatei und jede SEO-Plugin-Sitemap — sie ersetzt sie nicht.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Die WordPress-Kerndatei Sitemap listet alle deine Inhalts-URLs auf. Die LF-Sitemap zeigt Suchmaschinen, wie Sprachversionen zueinander in Beziehung stehen, über xhtml:link hreflang Alternativen. Reiche beide bei Google Search Console für vollständige Abdeckung ein.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s ist aktiv und generiert eine eigene Sitemap. Diese Sitemap ist getrennt von LF\'s. Beide sollten bei Google Search Console eingereicht werden: die SEO-Plugin-Sitemap listet deine Inhalte, die LF-Sitemap fügt die mehrsprachigen Alternativlinks hinzu. Die LF-Sitemap wird automatisch in robots.txt angekündigt.','Sitemap settings saved.'=>'Sitemap-Einstellungen gespeichert.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Sitemap-Cache geleert. Wird beim nächsten Besuch der Sitemap-URL neu generiert.','Sitemap output'=>'Sitemap-Ausgabe','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Generiere die mehrsprachige Sitemap unter /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Wenn aktiviert, wird die Sitemap-URL automatisch in robots.txt angekündigt und der Cache beim Speichern übersetzter Inhalte aktualisiert.','Sitemap URL'=>'Sitemap-URL','Submit this URL to Google Search Console alongside your main sitemap.'=>'Reiche diese URL zusammen mit deiner Haupt-Sitemap bei Google Search Console ein.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Noch nicht generiert. Die Sitemap wird beim ersten Besuch der Sitemap-URL erstellt und für 24 Stunden zwischengespeichert.','✓ Active — %d URL entry with language alternates'=>'✓ Aktiv — %d URL-Eintrag mit Sprachalternativen' . "\0" . '✓ Aktiv — %d URL-Einträge mit Sprachalternativen','No translated content found. The sitemap will populate once posts have been translated.'=>'Kein übersetzter Inhalt gefunden. Die Sitemap wird gefüllt, sobald Beiträge übersetzt sind.','Last generated: %s'=>'Zuletzt generiert: %s','Save Sitemap Settings'=>'Sitemap-Einstellungen speichern','Flush Sitemap Cache'=>'Sitemap-Cache leeren','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Erzwingt die Neugenerierung der Sitemap bei der nächsten Anfrage. Nach Massenimporten oder manuellen Änderungen an Übersetzungsbeziehungen verwenden.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow ist ein offenes Protokoll, das von Bing, Yandex und anderen Suchmaschinen unterstützt wird. Wenn ein übersetzter Beitrag veröffentlicht oder aktualisiert wird, benachrichtigt Lingua Forge automatisch alle teilnehmenden Engines in einem einzigen Push — kein Polling, kein Warten auf den nächsten robots.txt-Crawl.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow ersetzt die veralteten Bing- und Yandex-Sitemap-Ping-Endpunkte. Google entdeckt Sitemaps wie zuvor über die robots.txt Sitemap-Direktive.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Alle URLs erfolgreich an IndexNow übermittelt.','No translated URLs found to submit. Publish some translated posts first.'=>'Keine übersetzten URLs zum Einreichen gefunden. Veröffentliche zuerst einige übersetzte Beiträge.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow-Einreichung fehlgeschlagen. Überprüfe, ob die Schlüsseldatei öffentlich erreichbar ist (siehe unten) und versuche es erneut.','Verification key'=>'Verifizierungsschlüssel','Key file served automatically at: %s'=>'Schlüsseldatei automatisch bereitgestellt unter: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Der Schlüssel konnte nicht generiert werden. Überprüfe, ob die Website Schreibzugriff auf WordPress-Optionen hat.','Key file status'=>'Status der Schlüsseldatei','✓ Key file is publicly reachable.'=>'✓ Schlüsseldatei ist öffentlich erreichbar.','✗ Key file is not reachable.'=>'✗ Schlüsseldatei ist nicht erreichbar.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow-Engines überprüfen die Schlüsseldatei, bevor sie Einreichungen akzeptieren. Wenn die Datei nicht erreichbar ist, werden Einreichungen mit einem 403-Fehler abgelehnt.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Häufige Ursachen: Full-Page-Caching (löschen), ein Sicherheits-Plugin, das .txt-Dateien blockiert, oder eine benutzerdefinierte Nginx/Apache-Regel. Die Datei wird bei jeder Anfrage von LF bereitgestellt — keine physische Datei wird auf die Festplatte geschrieben.','Submit all URLs'=>'Alle URLs einreichen','Submit all URLs via IndexNow'=>'Alle URLs via IndexNow einreichen','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Schickt jede veröffentlichte, LF-verwaltete URL in einem Batch an IndexNow. Die automatische Einreichung läuft bereits bei jeder Veröffentlichung/Aktualisierung — benutze dies nur nach einem Massenimport oder bei der erstmaligen Einrichtung von IndexNow.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google nimmt nicht an IndexNow teil. Es entdeckt Sitemaps über die robots.txt Sitemap: Direktive – die LF bereits konfiguriert hat. Verwenden Sie Google Search Console, um die Indexierungsabdeckung zu überwachen.','Open Search Console →'=>'Open Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt mit Sitemap-Direktive aktualisiert.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Physische robots.txt gefunden. LF\'s Sitemap-Direktive ist vorhanden.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Es existiert eine physische robots.txt-Datei an der Site-Root. WordPress\' virtuelle robots.txt — und LF\'s Sitemap: Filter — werden umgangen. Die LF-Sitemap wird nicht an Suchmaschinen angekündigt.','Add Sitemap directive to robots.txt'=>'Füge die Sitemap-Direktive zu robots.txt hinzu.','Appends the following line to your existing robots.txt: %s'=>'Fügt die folgende Zeile zu deiner bestehenden robots.txt hinzu: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS ist gesetzt.','Add the following line to your robots.txt manually:'=>'Füge die folgende Zeile manuell zu deiner robots.txt hinzu:','View current robots.txt'=>'Aktuelles robots.txt anzeigen','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Keine physische robots.txt-Datei gefunden. WordPress generiert sie virtuell, und die Sitemap-Direktive von LF ist automatisch enthalten.','The following directive is active in your virtual robots.txt:'=>'Die folgende Direktive ist in deiner virtuellen robots.txt aktiv:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Dateibearbeitungen sind deaktiviert (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Konnte nicht in robots.txt schreiben. Überprüfe die Dateiberechtigungen.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge erweitert den WordPress Core Social Icons-Block mit dynamischen Share-URLs. Stelle den Link eines Symbols auf einen "share:"-Wert ein, und LF schreibt ihn beim Rendern in die richtige Share-URL oder JavaScript-Aktion um — ohne benutzerdefinierten Code oder Drittanbieter-Plugins.','Social Share settings saved.'=>'Einstellungen für soziale Freigabe gespeichert.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Das lf-social-share Mu-Plugin ist aktiv. Das integrierte Social Share von Lingua Forge ist inaktiv — das Mu-Plugin übernimmt die Umschreibung der Share-URL und die JS-Aktionen.','Social Share'=>'Social Share','Enable Social Share URL rewriting for Social Icons blocks'=>'Aktiviere Social Share URL-Umschreibung für Social Icons Blöcke','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Deaktiviert, weil das lf-social-share mu-plugin diese Funktion bereits bereitstellt.','Save Social Share Settings'=>'Social Share-Einstellungen speichern','How to use'=>'Anleitung','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Im Block-Editor füge einen Social Icons Block hinzu. Für jedes Icon öffne die Link-Einstellungen und gib einen der "share:"-Werte unten als URL ein. Im Frontend ersetzt LF es durch die korrekte Share-URL für die aktuelle Seite.','External share services'=>'Externe Share-Dienste','URL to enter'=>'URL zum Eingeben','Action'=>'Aktion','Share on Facebook'=>'Auf Facebook teilen','Post on X / Twitter'=>'Beitrag auf X / Twitter','Share on LinkedIn'=>'Auf LinkedIn teilen','Send via WhatsApp'=>'Per WhatsApp senden','Send via Telegram'=>'Per Telegram senden','Submit to Reddit'=>'Bei Reddit einreichen','Pin on Pinterest'=>'Auf Pinterest pinnen','Share on Mastodon'=>'Auf Mastodon teilen','Share via email (mailto:)'=>'Per E-Mail teilen (mailto:)','JavaScript-powered actions'=>'JavaScript-gesteuerte Aktionen','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopiere die aktuelle URL in die Zwischenablage. Zeigt bei Erfolg eine "Link kopiert"-Benachrichtigung.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Öffne das native Web Share Sheet des Browsers (iOS, Android, einige Desktops). Falls nicht unterstützt, wird auf die Zwischenablage zurückgegriffen.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Native Freigabe verwenden, wenn verfügbar; sonst auf Zwischenablage-Kopie zurückgreifen. Empfohlene Standardeinstellung für "Teilen"-Buttons.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Die Share-URL spiegelt immer die aktuelle Seite wider — keine manuelle URL-Eingabe erforderlich. Der Filter linguaforge_social_share_url ermöglicht es, die aufgelöste URL für jeden Dienst zu überschreiben.','Configuration issue: WP site language has no content on this site'=>'Konfigurationsproblem: Die Sprache der WP-Website hat keinen Inhalt auf dieser Website','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'Die WordPress-Seitensprache (%1$s) wird dem Sprachcode „%2$s" zugeordnet, aber es gibt keine Beiträge auf dieser Website mit dem Tag _lf_lang=%2$s. Dies führt dazu, dass WooCommerce-Produktabfragen null Ergebnisse zurückgeben, Produktbilder fehlschlagen und alle sprachgefilterten Inhaltsabfragen unterbrochen werden.','Fix: go to'=>'Fix: gehe zu','Settings → General → Site Language'=>'Einstellungen → Allgemein → Seiten-Sprache','and set it to one of your actual content languages (e.g. %s).'=>'und stellen Sie es auf eine Ihrer tatsächlichen Inhaltssprachen ein (z. B. %s).','Environment'=>'Umgebung','Lingua Forge version'=>'Lingua Forge Version','WordPress version'=>'WordPress-Version','PHP version'=>'PHP-Version','Active theme'=>'Aktives Theme','(FSE / block theme)'=>'(FSE / Block-Theme)','(classic theme)'=>'(klassisches Theme)','URL structure'=>'URL-Struktur','Subdomain (de.example.com)'=>'Subdomain (de.beispiel.com)','Path prefix (/de/)'=>'Pfadpräfix (/de/)','WP instance language'=>'WP-Instanzsprache','not a content language — see notice above'=>'keine Inhaltsprache — siehe Hinweis oben','Primary content language'=>'Primäre Inhaltssprache','Active languages'=>'Aktive Sprachen','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Kein PHP-Limit','(server/FPM timeout still applies)'=>'(Server/FPM-Timeout gilt weiterhin)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'KI-Übersetzung und Batch-Analyse können Zeitüberschreitungen verursachen. Empfohlen: 120s oder mehr.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'KI-Konfiguration','(active)'=>'(aktiv)','Configured'=>'Konfiguriert','No key'=>'Kein Schlüssel','— AI features are disabled.'=>'— KI-Funktionen sind deaktiviert.','Add key →'=>'Schlüssel hinzufügen →','Light model'=>'Leichtes Modell','Quality model'=>'Qualitätsmodell','Active preset'=>'Aktives Preset','Daily quota'=>'Tägliches Kontingent','Unlimited'=>'Unbegrenzt','requests / day'=>'Anfragen / Tag','Permalink Structure'=>'Permalink-Struktur','Permalink structure is compatible with Lingua Forge path routing.'=>'Permalink-Struktur ist kompatibel mit Lingua Forge Pfadrouting.','Plain permalinks are not supported.'=>'Einfache Permalinks werden nicht unterstützt.','Path routing requires a post-name based permalink structure. Change it in'=>'Pfadrouting erfordert eine Permalink-Struktur basierend auf Post-Namen. Ändere es in','Settings → Permalinks'=>'Einstellungen → Permalinks','Numeric permalink structure is not supported.'=>'Numerische Permalink-Struktur wird nicht unterstützt.','Switch to a post-name based structure in'=>'Wechsle zu einer post-namenbasierten Struktur in','SEO Plugins'=>'SEO-Plugins','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Keine Drittanbieter-SEO-Plugins erkannt. Lingua Forge übernimmt die gesamte mehrsprachige SEO-Ausgabe.','Active: %s.'=>'Aktiv: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Siehe Einstellungen → SEO → Kompatibilität für die vollständige Tabelle des Verhaltens pro Funktion.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce ist nicht aktiv.','Shop'=>'Shop','Cart'=>'Warenkorb','Checkout'=>'Kasse','My Account'=>'Mein Konto','WooCommerce version'=>'WooCommerce-Version','Order storage'=>'Bestandsverwaltung','High-Performance Order Storage (HPOS)'=>'Hochleistungs-Order-Speicherung (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Benutzerdefinierte Tabellen — LF-Post-Meta-Filter beeinflussen keine Bestellungen.','Shared / compatibility mode'=>'Gemeinsamer / Kompatibilitätsmodus','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT synchronisiert — Übergang; LF-Post-Meta-Filter gelten für die CPT-Kopie.','Legacy post-based (CPT)'=>'Legacy-Beiträge-basiert (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Bestellungen in wp_posts — stelle sicher, dass shop_order vom LF-Routing ausgeschlossen ist.','WcPageBridge active'=>'WcPageBridge aktiv','Yes'=>'Ja','No — WooCommerce integration class not loaded'=>'Keine — WooCommerce-Integrationsklasse nicht geladen','WooCommerce page translations'=>'WooCommerce-Seitenübersetzungen','No secondary languages configured.'=>'Keine sekundären Sprachen konfiguriert.','Active Plugins'=>'Aktive Plugins','No active plugins detected.'=>'Keine aktiven Plugins erkannt.','Version'=>'Version','_lf_lang Coverage'=>'_lf_lang Abdeckung','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Beiträge ohne _lf_lang sind für jeden Lingua Forge-Sprachfilter unsichtbar. Dies kann passieren, wenn Inhalte importiert oder vor der Aktivierung des Plugins erstellt wurden.','All published posts have a _lf_lang value. No gaps detected.'=>'Alle veröffentlichten Beiträge haben einen _lf_lang-Wert. Keine Lücken erkannt.','Missing'=>'Fehlt','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Diesen Beitragstyp vom Sprachrouting ausschließen — seine Beiträge erscheinen hier nicht mehr oder erhalten _lf_lang. Dies kann nicht automatisch rückgängig gemacht werden.','Exclude from routing'=>'Vom Routing ausschließen','excluded from routing'=>'vom Routing ausgeschlossen','Destructive action — read before proceeding'=>'Zerstörerische Aktion — vor dem Fortfahren lesen','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Repariere Tags bei jedem routbaren Beitrag, der oben aufgelistet ist, mit _lf_lang = %s. Beiträge in Routing-ausgeschlossenen Beitragstypen werden nicht berührt. Führe dies nur nach dem Importieren von Inhalten oder bei der ersten Aktivierung aus — nicht als Massen-Sprachzuweisungswerkzeug verwenden.','Repair — assign _lf_lang = %s to all routable posts above'=>'Reparieren — weise _lf_lang = %s allen oben genannten routbaren Beiträgen zu','Rewrite Rules'=>'Rewrite-Regeln','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF-eigene Einträge, die derzeit in $wp_rewrite->extra_rules_top registriert sind. Nützlich bei der Diagnose von 404-Fehlern oder Routing-Konflikten. Kopiere diese beim Einreichen eines Bugs.','%d rule registered'=>'%d Regel registriert' . "\0" . '%d Regeln registriert','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Keine LF-Rewrite-Regeln gefunden. Permalinks leeren, falls dies unerwartet ist.','Debug Info'=>'Debug-Info','Copy and paste into a GitHub issue or support request.'=>'In eine GitHub-Issue oder Support-Anfrage kopieren und einfügen.','Copy system info'=>'Systeminformationen kopieren','Copied!'=>'Kopiert!','Repairing…'=>'Reparatur läuft…','Repair failed.'=>'Reparatur fehlgeschlagen.','Network error.'=>'Netzwerkfehler.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Diesen Beitragstyp vom Sprachrouting ausschließen? Seine Beiträge erscheinen nicht mehr in dieser Liste oder erhalten _lf_lang. Du kannst das in Einstellungen → Router → Query-Filter-Ausnahmen rückgängig machen.','Excluding…'=>'Ausschließen…','Failed to save exclusion.'=>'Ausschluss konnte nicht gespeichert werden.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d Beitrag mit _lf_lang = %2$s getaggt.' . "\0" . '%1$d Beiträge mit _lf_lang = %2$s getaggt.','Uninstall Behaviour'=>'Deinstallationsverhalten','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Steuert, was passiert, wenn ein Administrator das Plugin in Plugins → Installierte Plugins → Löschen entfernt. Plugin-Einstellungen und AI-Caches werden immer entfernt. Sprachzuweisungen und Übersetzungsbeziehungen bleiben standardmäßig erhalten, damit eine versehentliche Deinstallation oder Neuinstallation dort anknüpfen kann, wo sie aufgehört hat.','Uninstall setting saved.'=>'Deinstallations-Einstellung gespeichert.','Delete content data on uninstall'=>'Inhalt bei Deinstallation löschen','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Auch Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Glossar und Übersetzungsspeicher löschen, wenn das Plugin deinstalliert wird.','Warning:'=>'Warnung:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Wenn aktiviert, werden bei der Deinstallation alle Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Seiten-Voreinstellungen, das AI-Glossar und der Übersetzungsspeicher für jede Seite auf dieser Seite dauerhaft gelöscht. Dies kann nicht rückgängig gemacht werden. Nicht aktivieren, wenn du den mehrsprachigen Support vollständig entfernen möchtest.','Save Uninstall Setting'=>'Deinstallations-Einstellung speichern','Today'=>'Heute','Last 7 days'=>'Letzte 7 Tage','Last 30 days'=>'Letzte 30 Tage','All time'=>'Alle Zeiten','AI Usage'=>'KI-Nutzung','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Token-Verbrauch nach Funktion, Anbieter und Modell zusammengefasst. Wird bei jedem erfolgreichen KI-Aufruf aufgezeichnet; Testverbindungspings werden ausgeschlossen, damit sie die Gesamtsumme nicht verfälschen.','Check your account, billing, or remaining credits directly on the provider console:'=>'Überprüfe dein Konto, Abrechnung oder verbleibende Credits direkt in der Anbieter-Konsole:','Anthropic Console'=>'Anthropic-Konsole','OpenAI Platform'=>'OpenAI Plattform','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Noch keine KI-Nutzung aufgezeichnet. Sobald ein Editor eine Übersetzung durchführt, eine Meta-Beschreibung generiert oder eine andere KI-Funktion nutzt, erscheinen hier die Gesamtsummen.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Keine KI-Nutzung im ausgewählten Zeitraum (%s) aufgezeichnet. Wähle oben einen größeren Zeitraum.','Provider'=>'Anbieter','Model'=>'Modell','Requests'=>'Anfragen','Input tokens'=>'Eingabe-Token','Output tokens'=>'Ausgabe-Token','Total tokens'=>'Gesamt-Token','Total'=>'Gesamt','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge fügt WooCommerce-spezifische Open Graph-Eigenschaften zu Produktseiten hinzu, damit beim Teilen einer Produkt-URL auf Facebook, Pinterest und ähnlichen Plattformen der richtige Produkttyp, Preis und Verfügbarkeit angezeigt werden.','WooCommerce SEO settings saved.'=>'WooCommerce SEO-Einstellungen gespeichert.','Product Open Graph'=>'Produkt Open Graph','Add WooCommerce product tags to Open Graph output'=>'Füge WooCommerce-Produkt-Tags zur Open Graph-Ausgabe hinzu.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Wenn aktiviert, gibt Lingua Forge die folgenden zusätzlichen Meta-Tags auf Produktseiten aus: og:type=product, og:price:amount, og:price:currency, og:availability und ihre product: Namespace-Äquivalente, die vom Facebook-Katalog verwendet werden.','Tags emitted'=>'Ausgesendete Tags','Tag'=>'Tag','Value source'=>'Wertquelle','"product" (replaces "article")'=>'„Produkt“ (ersetzt „Artikel“)','WooCommerce product price'=>'WooCommerce-Produktpreis','WooCommerce store currency'=>'Währung des WooCommerce-Shops','instock / oos / pending from WC stock status'=>'Auf Lager / Nicht auf Lager / Ausstehend aus WC-Lagerstatus','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Preis und Verfügbarkeit spiegeln immer das Produkt in der Quellsprache wider (gemeinsames Lagerbestandmodell). Tags werden nur ausgegeben, wenn LF\'s Open Graph-Modul auf "Voll" oder "Auto" eingestellt ist und kein widersprüchliches SEO-Plugin erkannt wird.','Save WooCommerce SEO Settings'=>'WooCommerce SEO-Einstellungen speichern','AI Provider'=>'KI-Anbieter','AI Usage & Cache'=>'KI-Nutzung & Cache','API Keys'=>'API-Schlüssel','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Schlüssel werden vor der Speicherung in der WordPress-Datenbank mit AES-256-CBC verschlüsselt. Das Verschlüsselungsgeheimnis wird aus deinen WordPress-Auth-Salzen (wp-config.php) abgeleitet, sodass Klartext-Schlüssel die Datenbank nie berühren.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API-Anmeldeinformationen werden in %s von WordPress verwaltet. Kein Schlüssel wird von Lingua Forge gespeichert.','Settings → Connectors'=>'Einstellungen → Konnektoren','API Key'=>'API-Schlüssel','Paste your API key…'=>'Füge deinen API-Schlüssel ein…','✓ Configured'=>'✓ Konfiguriert','✗ Not configured'=>'✗ Nicht konfiguriert','Test connection'=>'Verbindung testen','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lass es frei, um den bestehenden Schlüssel beizubehalten. Gib einen neuen Wert ein, um ihn zu ersetzen.','Remove stored key'=>'Gespeicherten Schlüssel entfernen','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Dieser Schlüssel wird derzeit von einem Server %s bereitgestellt und kann hier nicht entfernt werden. Gib oben einen neuen Schlüssel ein, um ihn mit einem Datenbankwert zu überschreiben.','environment variable'=>'Umweltvariable','PHP constant'=>'PHP-Konstante','Alternative (server-side):'=>'Alternativ (Server-seitig):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Du kannst Schlüssel auch als Konstanten oder Umweltvariablen definieren (z.B. in wp-config.php). Diese Quellen werden automatisch als Fallback verwendet, wenn kein Datenbankschlüssel gespeichert ist.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Um einen benutzerdefinierten Verschlüsselungsgeheimnis zu verwenden (anstatt des abgeleiteten wp_salt-Werts), füge dies in wp-config.php hinzu:','Unknown provider.'=>'Unbekannter Anbieter.','No API key configured for this provider.'=>'Für diesen Anbieter ist kein API-Schlüssel konfiguriert.','Could not instantiate the provider.'=>'Der Anbieter konnte nicht instanziiert werden.','Provider returned no response. Check the WordPress error log for details.'=>'Der Anbieter hat keine Antwort zurückgegeben. Überprüfe das WordPress-Fehlerprotokoll für Details.','Enter a model identifier to test.'=>'Geben Sie eine Modellkennung zum Testen ein.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Kein veröffentlichter Beitrag oder Seite zum Testen gefunden — veröffentlichen Sie zunächst Inhalte oder versuchen Sie Quick Translate direkt.','(untitled)'=>'(Ohne Titel)','Prompt template not found.'=>'Prompt-Template nicht gefunden.','Translation failed. Please try again.'=>'Übersetzung fehlgeschlagen. Bitte versuchen Sie es erneut.','The sample post has no visible text content to translate.'=>'Der Beispielbeitrag hat keinen sichtbaren Textinhalt zum Übersetzen.','Chunk prompt template not found.'=>'Chunk-Prompt-Template nicht gefunden.','Model returned no response. Check the WordPress error log for details.'=>'Modell gab keine Antwort. Überprüfen Sie das WordPress-Fehlerprotokoll für Details.','Behavior'=>'Verhalten','Block Editor'=>'Block-Editor','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge beschränkt standardmäßig zwei Gutenberg-Funktionen, um das redaktionelle Verhalten in allen Sprachen konsistent zu halten. Hier kannst du dich anmelden, wenn du volle Gutenberg / FSE-Fähigkeiten benötigst.','Block locking'=>'Block-Sperre','Allow editors to lock individual blocks'=>'Erlaube Redakteuren, einzelne Blöcke zu sperren','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Aktiviert wieder Gutenberg\'s canLockBlocks. Nützlich für redaktionelle Vorlagen, die verhindern sollen, dass Mitwirkende bestimmte Blöcke verschieben oder löschen.','Template mode'=>'Vorlagenmodus','Allow Gutenberg template-editing mode on post screens'=>'Erlaube Gutenberg-Vorlagenbearbeitungsmodus auf Beitragsseiten','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Aktiviert supportsTemplateMode. Kern für Full-Site-Editing-Workflows, bei denen Beitragsübergreifende Vorlagenüberschreibungen beabsichtigt sind.','Compliance Preset'=>'Compliance-Voreinstellung','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strenger Erhaltungsmodus für rechtliche, regulatorische, medizinische oder technische Inhalte. Wenn aktiviert, verwendet jede KI-Funktion eine niedrige Abtasttemperatur und fügt die nachstehende Ergänzung an den Systemprompt an — Terminologie, Artikelnumer, Einheiten, Markennamen und regulatorische Sprache werden wortwörtlich beibehalten, anstatt umformuliert zu werden.','Global AI preset'=>'Globale KI-Voreinstellung','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, pro Funktion','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Legt das Standardverhalten der KI für alle Funktionen site-weit fest. Einzelne Beiträge können dies für Übersetzungen und Inhaltserstellung über die Meta-Box von Lingua Forge überschreiben.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard verwendet die eigene abgestimmte Temperatur jeder Funktion: Übersetzung T=0.2 (präzise), Schnelle Übersetzung T=0.4, Inhaltserstellung T=0.6 (kreativ). Die anderen Voreinstellungen verwenden eine einzelne feste Temperatur für alle Funktionen.','Technical / Scientific instructions'=>'Technische / Wissenschaftliche Anweisungen','Legal / Compliance instructions'=>'Rechtliche / Compliance-Anweisungen','Creative / Marketing instructions'=>'Kreative / Marketing-Anweisungen','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lass es frei, um den integrierten Standard zu verwenden. Das Löschen einer gespeicherten Überschreibung stellt den Standard beim nächsten Speichern wieder her.','View built-in default'=>'Integrierten Standard anzeigen','Automatic Translation Backfill'=>'Automatisches Auffüllen von Übersetzungen','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Scannt regelmäßig nach Beiträgen, die eine Übersetzung in einer aktiven Sprache fehlt, und stellt eine KI-Übersetzung für jede gefundene Lücke in die Warteschlange — die gleiche Wiederherstellung, die Sie bereits manuell über "Fehlende übersetzen" oder die WP-CLI-Befehle missing_translations/fill_translations auslösen können, automatisch stattdessen einmal pro Stunde ausgeführt.','Automatic backfill'=>'Automatisches Auffüllen','Automatically translate posts missing a language version'=>'Übersetzen Sie automatisch Beiträge, denen eine Sprachversion fehlt','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Standardmäßig deaktiviert. Diese Funktion führt KI-Provider-Anfragen durch — und verursacht die damit verbundenen API-Kosten — automatisch und im Hintergrund, ohne Bestätigung pro Anfrage, für jeden veröffentlichten Beitrag ohne Übersetzung in einer aktiven Sprache. Aktivieren Sie dies nur, wenn Sie möchten, dass jede Inhaltslücke unbeaufsichtigt übersetzt wird; verwenden Sie andernfalls "Fehlende übersetzen" oder die WP-CLI-Befehle, um nach Ihrem eigenen Zeitplan zu übersetzen.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'WooCommerce-Produkte und Varianten werden niemals einbezogen, unabhängig von dieser Einstellung. Eine Integration kann auch bestimmte Beitragstypen über den Filter linguaforge_cpt_create_allowed blockieren.','Comment Translation'=>'Kommentarübersetzung','Mirrors an approved comment onto every language version of the post it belongs to, translated, as a real comment on each sibling page. Off by default.'=>'Spiegelt einen genehmigten Kommentar auf jede Sprachversion des zugehörigen Beitrags, übersetzt, als echter Kommentar auf jeder Geschwisterseite. Standardmäßig deaktiviert.','Comment translation'=>'Kommentarübersetzung','Enable comment translation'=>'Kommentarübersetzung aktivieren','Off by default. This feature makes AI provider requests — and spends the associated API cost — for approved comments on any post that has translated language versions. WooCommerce product reviews are never included; they already share one review pool across languages.'=>'Standardmäßig deaktiviert. Diese Funktion führt Anfragen an den KI-Anbieter durch – und verursacht die damit verbundenen API-Kosten – für genehmigte Kommentare zu jedem Beitrag, der übersetzte Sprachversionen hat. WooCommerce-Produktbewertungen sind niemals eingeschlossen; sie teilen bereits einen Bewertungspool über die Sprachen hinweg.','Translation trigger'=>'Übersetzungs-Trigger','Manual — translate only via the Comments screen action'=>'Manuell – nur über die Aktion auf dem Bildschirm Kommentare übersetzen','Automatic — translate every comment as soon as it\'s approved'=>'Automatisch – jeden Kommentar direkt nach seiner Genehmigung übersetzen','Manual (default) queues nothing automatically — use the "Translate missing" bulk action on the Comments screen on your own schedule. Automatic queues a translation the moment a comment is approved (or arrives already-approved), which can spend API calls on comments a moderator was about to reject if there\'s a large held-for-moderation backlog.'=>'Manuell (Standard) stellt nichts automatisch in Warteschlange – verwenden Sie die Bulk-Aktion "Fehlende übersetzen" auf dem Bildschirm Kommentare nach Ihrem eigenen Zeitplan. Automatisch stellt eine Übersetzung in Warteschlange, sobald ein Kommentar genehmigt wird (oder bereits genehmigt ankommt), was API-Aufrufe für Kommentare kosten kann, die ein Moderator gerade ablehnen wollte, wenn es einen großen Rückstand an moderierten Kommentaren gibt.','Max nested-reply depth'=>'Maximale Tiefe der geschachtelten Antworten','How many levels of nested replies "Translate missing" will walk and translate in one pass, counting the original top-level comment as level 0. Default 2 covers the original comment plus replies and replies-to-replies. Bounds AI spend on deep threads — anything nested deeper isn\'t backfilled until this is raised or a further pass runs.'=>'Wie viele Ebenen geschachtelter Antworten "Fehlende übersetzen" in einem Durchgang durchlaufen und übersetzen wird, wobei der ursprüngliche oberste Kommentar als Ebene 0 zählt. Standardwert 2 deckt den ursprünglichen Kommentar sowie Antworten und Antworten auf Antworten ab. Begrenzt die Ausgaben der KI bei tiefen Threads – alles, was tiefer geschachtelt ist, wird nicht aufgefüllt, bis dies erhöht wird oder ein weiterer Durchgang durchgeführt wird.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Die Schaltfläche "Sync" in der Lang-Spalte der Beitragsliste übersetzt einen Beitrag in jede andere Sprache, einschließlich der Primär-/Ausgangssprache, wenn sie von einer Übersetzung aus ausgeführt wird. Diese Rück-Übersetzungsrichtung ist standardmäßig für jeden Beitragstyp eingeschränkt. (WooCommerce-Produkte und Varianten haben ihre eigene separate Einstellung unten — diese betrifft sie nicht.)','Secondary-language Sync'=>'Sync in Sekundärsprache','Allow "Sync" on a translated post to overwrite the primary post'=>'Erlauben Sie "Sync" auf einer übersetzten Seite, den primären Beitrag zu überschreiben','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Standardmäßig deaktiviert: Klicken auf "Sync" auf einer Übersetzung wird blockiert, um den primären Beitrag nicht zu überschreiben. Das Synchronisieren VOM primären Beitrag zu jeder Übersetzung ist immer erlaubt, unabhängig von dieser Einstellung. Aktivieren Sie dies nur, wenn Sie absichtlich möchten, dass eine Übersetzung zur neuen Quelle werden kann.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Das Primärsprachen-Produkt ist die operative Quelle der Wahrheit von WooCommerce für Preis, SKU und Bestand, die immer von ihm bereitgestellt werden, unabhängig davon, welche Sprache ein Käufer anzeigt. Dies ist eine separate, unabhängige Einstellung von der allgemeinen "Sync"-Einschränkung oben — das Aktivieren einer aktiviert nicht automatisch die andere.','Allow "Sync" on a translated product to overwrite the primary product'=>'Erlauben Sie "Sync" auf einem übersetzten Produkt, das primäre Produkt zu überschreiben','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Standardmäßig deaktiviert: Klicken auf "Sync" auf einem übersetzten WooCommerce-Produkt wird blockiert, da es den Titel, die Beschreibung und den Auszug des primären Produkts rück-übersetzen würde. Das Synchronisieren VOM primären Produkt zu jeder Übersetzung ist immer erlaubt, unabhängig von dieser Einstellung. Aktivieren Sie dies nur, wenn Sie absichtlich möchten, dass eine Übersetzung zur neuen Quelle werden kann.','General'=>'Allgemein','Light'=>'Leicht','Meta Description, Excerpt Generator, quick translate'=>'Meta-Beschreibung, Auszug-Generator, schnelle Übersetzung','Quality'=>'Qualität','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Vollseiten-Übersetzung, Inhaltsgenerator (Mid-Tier-Modelle sind voll ausreichend)','Active Provider'=>'Aktueller Anbieter','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Derzeit geerbt vom %s-Konstanten. Die Auswahl eines Werts hier überschreibt ihn.','WordPress AI Client — requirements:'=>'WordPress KI-Client — Anforderungen:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Vollseitenübersetzung verwendet JSON-schema-beschränkte Ausgabe. Dafür muss ein Connector-Plugin installiert und aktiviert sein (nicht nur ein API-Schlüssel in Einstellungen → Connectors gespeichert). Wenn die Übersetzung fehlschlägt, überprüfe das PHP-Fehlerprotokoll auf den spezifischen Fehler oder wechsle zu einem integrierten Anbieter.','Manage your account, review usage, or top up credits:'=>'Verwalte dein Konto, überprüfe die Nutzung oder lade Credits auf: ','WordPress Connectors'=>'WordPress-Konnektoren','Models'=>'Modelle','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funktionen sind in zwei Ebenen gruppiert. Gib die genaue Modellkennung für jede Ebene und jeden Anbieter ein. Lasse ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Nur die aktiven Anbieter-Modelle werden zur Laufzeit aufgerufen — konfiguriere die anderen im Voraus, wenn du planst zu wechseln.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Beginne in einem beliebigen Feld zu tippen, um Modellvorschläge zu sehen, oder verwende die Referenztabelle unten. Light- und Mid-Tier-Qualitätsmodelle (Haiku, GPT-4o mini, Gemini Flash) sind für Übersetzungen und Inhaltsgenerierung völlig ausreichend — Flaggschiff-"max"-Modelle erhöhen die Kosten mit minimalem Qualitätsgewinn für strukturierte Texte.','active'=>'aktiv','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Modellauswahl wird in %s von WordPress verwaltet — kein Modell-Identifikator wird von Lingua Forge für diesen Anbieter gespeichert.','overridden'=>'überschrieben','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Übersetzt ein kurzes Beispiel Ihres letzten veröffentlichten Beitrags mit genau diesem Modell — ein echter, abgerechneter API-Aufruf.','Test model'=>'Testmodell','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tipp: Um ein Modell auf den integrierten Standard zurückzusetzen, lösche das Feld und speichere.','Available models reference'=>'Verfügbare Modellreferenz','Model ID'=>'Modell-ID','Name'=>'Name','Tier'=>'Stufe','Notes'=>'Notizen','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Dieses Katalog wird bei jeder Lingua Forge-Version aktualisiert. Das Testen einer Verbindung im Tab API-Schlüssel ruft auch die Live-Modellliste vom Anbieter ab und aktualisiert die oben genannten Vorschläge.','Glossary'=>'Glossar','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Benutzerverwaltete Terminologietabelle pro Sprachpaar. Einträge werden an den Übersetzungssystemprompt angehängt, damit die KI bevorzugte Begriffe konsequent verwendet – entscheidend für Fachvokabular ("kWp", "PPA", "Anschlussstelle"), Markennamen, die nicht übersetzt werden dürfen, und standardisierte regulatorische Formulierungen. Beide Sprachfelder sind optional: Lass "Quellsprache" leer, um den Eintrag unabhängig von der Sprache, aus der du übersetzt, anzuwenden; lass "Zielsprache" leer, um ihn auf alle Zielsprache gleichzeitig anzuwenden.','Glossary entry added.'=>'Glossareintrag hinzugefügt.','Glossary entry removed.'=>'Glossareintrag entfernt.','Could not add entry: source term and target term are required.'=>'Eintrag konnte nicht hinzugefügt werden: Quell- und Zielbegriff sind erforderlich.','Could not save the glossary entry.'=>'Das Glossareintrag konnte nicht gespeichert werden.','Source language'=>'Quellsprache','— Any —'=>'— Beliebig —','Target language'=>'Zielsprache','— Any target —'=>'— Beliebige Zielsprache —','Filter'=>'Filter','Reset'=>'Zurücksetzen','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Keine Glossareinträge entsprechen dem aktuellen Filter. Entferne den Filter, um alle Einträge zu sehen, oder füge unten einen neuen Eintrag hinzu.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Noch keine Glossareinträge. Füge unten einen hinzu, um die Terminologie in Übersetzungen durchzusetzen.','Source term'=>'Quellbegriff','Target term'=>'Zielbegriff','Source lang'=>'Quell-Sprache','Target lang'=>'Ziel-Sprache','any'=>'beliebig','Delete this glossary entry?'=>'Diesen Glossareintrag löschen?','Add new entry'=>'Neuen Eintrag hinzufügen','The phrase as it appears in the source text.'=>'Der Ausdruck, wie er im Quelltext erscheint.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'So soll er in der Übersetzung erscheinen. Gib denselben Wert wie den Quellbegriff ein, um die KI anzuweisen, ihn wortwörtlich zu bewahren.','— Any source language —'=>'— Beliebige Quellsprache —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lass es leer für Markennamen und sprachunabhängige Begriffe, die unabhängig von der Sprache, aus der wir übersetzen, durchgesetzt werden sollen.','— Any target language —'=>'— Beliebige Zielsprache —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lass es leer, um diesen Eintrag auf alle Zielsprache anzuwenden – ideal für Markennamen, Abkürzungen und Begriffe, die in jeder Übersetzung wortwörtlich erhalten bleiben müssen.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Optionaler Kontext für Redakteure (z.B. "ASIC = Application-Specific Integrated Circuit; in technischen Kontexten auf Englisch belassen").','Add entry'=>'Eintrag hinzufügen','Limits'=>'Grenzen','Authors and above (edit_published_posts)'=>'Autoren und höher (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Mitwirkende und höher – Standard (edit_posts)','Editors and above (edit_others_posts)'=>'Redakteure und höher (edit_others_posts)','Administrators only (manage_options)'=>'Nur Administratoren (manage_options)','AI Limits & Security'=>'KI-Grenzen & Sicherheit','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Begrenze die Nutzung der KI auf der Seite und beschränke, welche Benutzerrollen kostenpflichtige KI-Anfragen auslösen dürfen. Überlagert die pro-Benutzer-Grenze (30 Anfragen / Minute, fest codiert), die bereits vor unkontrollierten Schleifen schützt.','Daily request limit'=>'Tägliches Anfrage-Limit','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Gesamtgrenze für KI-Anfragen pro UTC-Tag (zählt sowohl Toolbar-Übersetzungen als auch Block-Revisionen). Zählt bei UTC-Midnight zurück. Setze auf 0, um die Begrenzung zu deaktivieren.','Minimum role'=>'Mindestrolle','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Niedrigste WordPress-Fähigkeit, die zum Auslösen von KI-Funktionen erlaubt ist. Das Verschärfen auf Multi-Autor-Websites verhindert, dass Mitwirkende oder Testkonten kostenpflichtige KI-Anfragen ausführen. Überschreibe pro Funktion via den linguaforge_required_capability-Filter.','Translation Limits'=>'Übersetzungsbegrenzungen','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Steuere, wie viel Inhalt an die KI gesendet wird und wie groß die Antwort sein darf. Lass ein Feld leer, um den integrierten Standard zu verwenden (als Platzhalter angezeigt). Erhöhe diese Werte, wenn große Seiten abgeschnitten werden; senke sie, um API-Kosten zu reduzieren.','Model tier'=>'Modellstufe','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Standard – Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Licht (schnell und kosteneffizient – Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Welche Modellstufe für die Vollseitenübersetzung verwenden. Qualität nutzt das im obigen Modelle-Tabelle konfigurierte Modell und wird für genaue, längere Übersetzungen empfohlen. Wechsle nur zu Licht, wenn Geschwindigkeit oder Kosten Priorität haben und der Inhalt kurz ist.','Max output tokens'=>'Maximale Ausgaben-Tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximale Anzahl an Tokens, die die KI in einer einzigen Übersetzungsantwort produzieren darf. Wenn eine Übersetzung am Ende stillschweigend abgeschnitten wird, erhöhe diesen Wert. Standard: 16.000.','Max input characters'=>'Maximale Eingabebuchstaben','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximale Anzahl der Zeichen des Beitragsinhalts, die an die KI weitergeleitet werden. 0 bedeutet kein Limit – der vollständige Inhalt wird immer gesendet (empfohlen). Stelle nur einen nicht-null Wert ein, wenn dein Anbieter ein enges Kontextfenster hat. Eine Warnung wird in das PHP-Fehlerprotokoll geschrieben, wenn der Inhalt gekürzt wird.','Quick Translation'=>'Schnelle Übersetzung','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Schnelle Übersetzung wird im Snippet-/Chunk-Modus verwendet – kurze Passagen, die auf Abruf aus der Symbolleiste, dem Editor oder den Block-Popovers übersetzt werden. Es verwendet eine separate, leichtere Konfiguration als die Vollseitenübersetzung, um schnelle und kostengünstige Antworten zu gewährleisten.','Light (default — fast and cost-effective)'=>'Light (Standard – schnell und kostengünstig)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualität (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Die Light-Stufe verwendet das schnelle Modell, das in der oben stehenden Modellauswahl konfiguriert ist (Standard: Haiku / Flash). Wechsle zu Qualität, wenn du die gleiche Übersetzungsgenauigkeit wie im Vollseitenmodus für Snippets benötigst.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximale Tokens, die die KI pro schnelle Übersetzung produzieren darf. Standard: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximale akzeptierte Zeichen vom Eingabefeld. Standard: 8.000.','Content Generator'=>'Content-Generator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Steuert das Token-Budget und die Eingabebegrenzungen für die Funktion des KI-Content-Generators. Lasse die Felder leer, um die integrierten Standardwerte zu verwenden.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximale Tokens, die die KI pro Generationslauf produzieren darf. Erhöhe dies, wenn vollständige Artikel abgeschnitten werden. Standard: 8.192.','Max hints characters'=>'Max. Hinweise-Zeichen','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximale Zeichen, die aus dem Hinweise-Feld gelesen werden. Standard: 2.000.','Max context characters'=>'Max. Kontextzeichen','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximale Zeichen des bestehenden Beitragsinhalts, die an die KI als Saatkontext übergeben werden, wenn keine Hinweise bereitgestellt werden. Standard: 6.000.','Maintenance'=>'Wartung','Router'=>'Router','Primary language saved.'=>'Primärsprache gespeichert.','Permalink rules flushed successfully.'=>'Permalink-Regeln erfolgreich gelöscht.','Language uninstalled. %d post deleted.'=>'Sprache deinstalliert. %d Beitrag gelöscht.' . "\0" . 'Sprache deinstalliert. %d Beiträge gelöscht.','%d locale file removed.'=>'%d Sprachdatei wurde entfernt.' . "\0" . '%d Sprachdateien wurden entfernt.','%d pattern translation removed.'=>'%d Muster-Übersetzung entfernt.' . "\0" . '%d Muster-Übersetzungen entfernt.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d Sprachdatei konnte nicht automatisch entfernt werden (DISALLOW_FILE_MODS ist aktiviert). Lösche sie manuell über deinen Server oder WP-CLI: wp language core uninstall <locale>.' . "\0" . '%d Sprachdateien konnten nicht automatisch entfernt werden (DISALLOW_FILE_MODS ist aktiviert). Lösche sie manuell über deinen Server oder WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Primärsprache','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Die primäre Sprache wird immer an der Wurzel deiner Seite bedient — kein URL-Präfix im Pfadmodus, keine Sprach-Subdomain im Subdomain-Modus. Alle anderen Sprachen verwenden entweder ein /lang/ Pfadpräfix (z.B. example.com/de/) oder eine Sprach-Subdomain (z.B. de.example.com), abhängig von der unten stehenden URL-Struktur-Einstellung.','Primary language'=>'Primärsprache','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Nach Änderung der primären Sprache die Permalinks (Abschnitt unten) aktualisieren, damit die URL-Routing-Änderungen wirksam werden.','Path prefix — example.com/de/'=>'Pfadpräfix — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Der Subdomain-Modus erfordert, dass dein Webserver alle Sprach-Subdomains (z.B. de.example.com) auf diese WordPress-Installation zeigt. Nach dem Wechsel des Modus, leere die Permalink-Regeln und lösche alle Caches. Wenn deine Start-URL www enthält (z.B. www.example.com), verwende den lf_base_domain Filter, um die reine Domain festzulegen, damit die Subdomains korrekt aufgebaut werden.','Browser language redirect'=>'Browser-Sprachumleitung','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Leite Besucher basierend auf dem Accept-Language-Header ihres Browsers auf ihre bevorzugte Sprache um','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wenn aktiviert, werden Erstbesucher ohne Sprach-Cookie und ohne Sprachpräfix in der URL auf die nächstgelegene passende Sprachversion umgeleitet. Die Umleitung wird übersprungen, wenn die bevorzugte Sprache des Browsers nicht zu den aktiven Router-Sprachen gehört. Sobald ein Besucher eine Sprache über den Schalter auswählt, hat das Cookie Vorrang und der Browser-Header wird bei zukünftigen Besuchen ignoriert.','Query Filter Exclusions'=>'Ausschlüsse für Query-Filter','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge beschränkt sekundäre WP_Query-Instanzen (Sidebar-Widgets, Template-Blöcke, Plugin-Lookups) auf die aktive Sprache, indem es eine _lf_lang Meta-Beschränkung injiziert. Die hier aufgeführten Beitragstypen sind von dieser Beschränkung ausgeschlossen — ihre Abfragen sind immer ungefiltert.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form), Flamingo-Kontakte und eingehende Nachrichten (flamingo_contact, flamingo_inbound) sowie WordPress-Sprachpaket-Synchronisierungsspeicher (wp_sync_storage) sind automatisch ausgeschlossen. Füge alle anderen Drittanbieter-Post-Typen hinzu, deren Inhalte nicht sprachgefiltert werden sollen, jeweils eine pro Zeile oder durch Kommas getrennt.','Excluded post types'=>'Ausgeschlossene Beitragstypen','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Post-Typ-Slugs, getrennt durch Kommas oder Zeilenumbrüche. Änderungen treten sofort nach dem Speichern in Kraft — kein Permalink-Flush erforderlich.','WooCommerce Integration'=>'WooCommerce-Integration','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Steuert, wie Lingua Forge in die WooCommerce-Bestellabwicklung integriert wird.','Order line item source mapping'=>'Quellzuordnung der Bestellpositionen','Normalize order line item product IDs to the source-language product at checkout'=>'Normalisiere Bestellpositionen-Produkt-IDs auf das Quellsprach-Produkt beim Checkout','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'Wenn aktiviert (empfohlen), wird die Produkt-ID, die bei jeder WooCommerce-Bestellung gespeichert ist, auf das Quellsprach-Produkt gesetzt. Das stellt sicher, dass total_sales-Zählungen, WC Analytics-Umsatzzeilen und Exporte von Drittanbieter-ERP auf eine Produkt-ID pro SKU anstatt pro Sprachversion verweisen. Nachteil: "Produkt anzeigen"-Links in Bestell-E-Mails und Mein Konto führen zur Quellsprachseite. Deaktiviere nur, wenn ein verbundenes System auf übersetzte Produkt-IDs in Bestellungen angewiesen ist. Verwende den Filter linguaforge_wc_order_item_source_mapping für einzelne Überschreibungen.','Save Router Settings'=>'Router-Einstellungen speichern','Flush Permalinks'=>'Permalinks leeren','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneriert die Rewrite-Regeln von WordPress, sodass URL-Präfixe, sprachspezifische Slugs und Archiv-Umleitungen synchron sind. Notwendig nach Änderung der Primärsprache oder Hinzufügen neuer Sprachunterstützung.','Flush Permalink Rules'=>'Permalink-Regeln leeren','Active Languages'=>'Aktive Sprachen','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Sprachen, die dem Router derzeit bekannt sind (abgeleitet von installierten WordPress-Lokalisierungspaketen plus der Primärsprache). Installiere zusätzliche Sprachpakete im unteren Abschnitt, um mehr Sprachen für Routing und Übersetzung verfügbar zu machen.','%d locale pack installed.'=>'%d Lokalisierungspaket installiert.' . "\0" . '%d Lokalisierungspakete installiert.','Install a Language'=>'Eine Sprache installieren','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Lade und installiere ein WordPress-Kern-Lokalisierungspaket direkt von WordPress.org. Nach der Installation steht die Lokalisierung für URL-Routing und den KI-Übersetzungsworkflow zur Verfügung. Die Liste der verfügbaren Sprachen wird bei Bedarf abgerufen — klicke auf die Schaltfläche unten, um sie zu laden.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Die Sprachinstallation ist auf diesem Server deaktiviert. Die Konstante DISALLOW_FILE_MODS ist in wp-config.php gesetzt. Installiere Sprachpakete manuell via WP-CLI: wp language core install de_DE','Load available languages'=>'Verfügbare Sprachen laden','— select a language —'=>'— wähle eine Sprache —','Install'=>'Installieren','Language Setup'=>'Sprachsetup','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Keine sekundären Sprachen konfiguriert. Installiere ein Sprachpaket oben, um die Vorlagenerstellung zu aktivieren.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wähle eine Sprache, um ihre FSE-Vorlagen, Vorlage-Teile und Navigationsmenüs zu verwalten.','Recreate All Languages'=>'Alle Sprachen neu erstellen','Recreate All Languages (Templates Only)'=>'Alle Sprachen neu erstellen (nur Vorlagen)','Recreate All Languages (Template Parts Only)'=>'Alle Sprachen neu erstellen (nur Vorlagenteile)','Cancel'=>'Abbrechen','Repair Template Metadata'=>'Vorlagen-Metadaten reparieren','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Behebt den Namensraum des Site Editors und das _lf_lang-Tag bei allen LF-gestützten FSE-Vorlagen, die in der Datenbank gespeichert sind. Führe dies einmal nach einem Update von einer früheren Version von Lingua Forge aus — es verschiebt WooCommerce-abgeleitete Vorlagen von der aktiven Theme-Gruppe in die WooCommerce-Gruppe im Site Editor und stellt sicher, dass alle vorgefertigten Vorlagen durch Berichtsübersichten auffindbar sind.','Repair template metadata'=>'Vorlagen-Metadaten reparieren','Request failed.'=>'Anfrage fehlgeschlagen.','Forbidden'=>'Verboten','Danger Zone'=>'Gefahrenzone','Uninstall %s'=>'Deinstalliere %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Dauerhaft alle Vorlagen, Vorlage-Teile, Muster, Navigationsmenüs, Beiträge, Seiten, benutzerdefinierte Beitragstypen, Produkte und Produktvariationen, die mit dieser Sprache verbunden sind, löschen. Entfernt auch die WordPress-Lokalisierungsdateien, sodass diese Sprache im Router nicht mehr erscheint. Diese Aktion kann nicht rückgängig gemacht werden.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Diese Sprache entspricht dem Locale deiner WordPress-Instanz und kann nicht deinstalliert werden.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Dauerhaft %s deinstallieren? Dies löscht alle übersetzten Inhalte für diese Sprache und kann nicht rückgängig gemacht werden.','Invalid language code.'=>'Ungültiger Sprachcode.','This language is protected and cannot be uninstalled.'=>'Diese Sprache ist geschützt und kann nicht deinstalliert werden.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Die Sprachinstallation ist auf diesem Server deaktiviert (DISALLOW_FILE_MODS ist gesetzt).','Invalid locale code.'=>'Ungültiger Lokalisierungscode.','Language %s installed successfully.'=>'Sprache %s erfolgreich installiert.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Die Installation des Sprachpakets ist fehlgeschlagen. Die Sprache ist möglicherweise bereits installiert, der Lokalisierungscode ist falsch oder dein Server blockiert Dateischreibrechte.','Navigations'=>'Navigationen','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigation-Übersetzung erfordert einen aktiven KI-Anbieter. Konfiguriere einen API-Schlüssel im Tab API-Schlüssel.','Navigation'=>'Navigation','Re-translate'=>'Neu übersetzen','CPT Block Patterns'=>'CPT-Blockmuster','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Blockmuster, die für benutzerdefinierte Beitragstypen registriert sind. Verwende die Übersetzen-Schaltfläche, um eine Sprachvariante zu erstellen. Der übersetzte Inhalt wird hier gespeichert und kann vom Block-Editor Pattern-Inserter in jeden CPT-Beitrag kopiert oder als Ausgangspunkt für ein synchronisiertes Muster (Wiederverwendeter Block) verwendet werden.','Pattern'=>'Muster','Post Types'=>'Beitragstypen','✓ Translation saved'=>'✓ Übersetzung gespeichert','View'=>'Ansicht','Template Parts'=>'Vorlagen-Teile','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Sprachspezifische Kopien der Vorlagen-Teile des Themes. Nach der Erstellung werden die Vorlagen aktualisiert, um auf den sprachspezifischen Teil zu verweisen.','Re-create all'=>'Alle neu erstellen','Translate all'=>'Alles übersetzen','Fix all links'=>'Alle Links reparieren','Fix all navs'=>'Alle Navigationselemente reparieren','Part'=>'Teil','Status / Actions'=>'Status / Aktionen','Create'=>'Erstellen','Templates'=>'Vorlagen','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-Vorlagen, die vom aktiven Theme vorgegeben sind. Erstelle sie und passe sie im Site Editor an.','Create missing'=>'Erstellen, was fehlt','Fix all parts'=>'Alle Teile reparieren','SEO'=>'SEO','Multilingual SEO'=>'Mehrsprachige SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Konfiguriere hreflang, Open Graph, Schema.org, Sitemaps und soziale Freigabe für jede Sprache auf deiner Seite. Jeder Abschnitt unten behandelt einen Aspekt der mehrsprachigen SEO.','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Schema.org'=>'Schema.org','Sitemap'=>'Sitemap','Analysis'=>'Analyse','Compatibility'=>'Kompatibilität','System'=>'System','Overview'=>'Übersicht','Lingua Forge Settings'=>'Lingua Forge-Einstellungen','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge fügt deiner WordPress-Seite mehrsprachiges Routing, KI-gestützte Übersetzung, hreflang-SEO-Tags und einen Sprachumschalter hinzu.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Verwende die Tabs oben auf dieser Seite, um jeden Bereich zu konfigurieren. Änderungen am Router-Tab treten sofort in Kraft; Änderungen an KI-Schlüsseln und Modelleinstellungen gelten für die nächste KI-Anfrage.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Nach Änderungen an den URL-Struktur-Einstellungen (Pfadpräfix ↔ Subdomain) besuche immer Einstellungen → Permalinks und klicke auf Änderungen speichern, um die Umschreibregeln zu aktualisieren.','AI Provider Tab'=>'AI-Anbieter-Tab','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Unterstützte Anbieter: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Wähle den aktiven Anbieter aus dem Dropdown — nur ein Anbieter wird gleichzeitig verwendet. Gib einen API-Schlüssel für diesen Anbieter ein, um AI-Funktionen zu aktivieren.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Schlüssel sind im Ruhezustand mit AES-256-GCM verschlüsselt, unter Verwendung eines sitespezifischen Geheimnisses (LINGUAFORGE_SECRET). Teile keine Datenbank-Exporte ohne vorheriges Rotieren des Geheimnisses.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'KI-Funktionen sind optional. Sprachrouting, hreflang, der Sprachumschalter und das Übersetzungsgruppensystem funktionieren alle ohne einen konfigurierten Anbieter.','Model tiers'=>'Modellstufen','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge verwendet zwei Modellstufen pro Anbieter:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Licht: Wird für Meta-Beschreibungen und Auszugserstellung verwendet — schnell, kostengünstig.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualität: Wird für Beitrag-Übersetzung und Inhaltserstellung verwendet — höhere Qualität, höhere Kosten.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Lass ein Modellfeld leer, um das integrierte Standardmodell für diese Ebene zu verwenden. Der Platzhalter zeigt an, welches Modell verwendet wird.','Translation Limits & Behavior'=>'Übersetzungsgrenzen & Verhalten','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Übersetzungsgrenzen: Steuere, welche Benutzerrollen die KI-Übersetzung auslösen können, und lege ein monatliches Token-Budget fest. Wenn das Budget überschritten wird, werden KI-Anfragen bis zum Monatswechsel ausgesetzt.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Verhalten: Wähle die KI-Voreinstellung (Wörtlich, Ausgewogen, Kreativ), füge siteweite benutzerdefinierte Anweisungen hinzu, aktiviere oder deaktiviere die automatische Übersetzung nach dem Speichern des Beitrags und konfiguriere die Übersetzungsspeicher.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Das Übersetzungsspeicher-Cache speichert KI-Ergebnisse anhand von Inhalts-Hash, Sprachpaar, Anbieter und Modell. Das Bearbeiten eines Beitrags invalidiert den Cache-Eintrag, sodass der nächste Übersetzungsaufruf ein frisches Ergebnis erhält.','Router Tab'=>'Router-Tab','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Primäre Sprache: die Sprache, in der dein bestehender Inhalt geschrieben ist. Alle Übersetzungen werden aus dieser Sprache erstellt; eine Änderung verschiebt oder löscht keine Beiträge.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-Struktur: Pfadpräfix-Modus (example.com/de/) erfordert keine Serveränderungen. Subdomain-Modus (de.example.com) benötigt einen Wildcard-DNS-Eintrag, ein Wildcard-SSL-Zertifikat und eine Änderung der Webserver-Konfiguration — siehe die Server-Einrichtungsanleitung.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktive Sprachen: Füge jede Sprache hinzu, die du unterstützen möchtest. Jede Sprache erhält ein URL-Präfix oder eine Subdomain und ein hreflang-Tag im &lt;head&gt; der Seite.','WP site language requirement'=>'Anforderung an die WP-Website-Sprache','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Die Sprache der WordPress-Website (Einstellungen → Allgemein → Seitensprache) muss auf eine der Sprachen eingestellt sein, die du für Inhalte verwendest — entweder die primäre Inhaltsprache oder eine der Sekundärsprachen. Es kann keine Sprache sein, die keinen Inhalt auf der Seite hat.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Beispiel für eine unterstützte Konfiguration: WP-Seiten-Sprache = Katalanisch (CA), Inhaltssprachen = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Beispiel für eine nicht unterstützte Konfiguration: WP-Seiten-Sprache = Englisch (EN), Inhaltssprachen = nur CA + ES. Englisch ist keine Inhaltsprache, daher kann Lingua Forge die WP-Lokale nicht einer Übersetzungsgruppe zuordnen.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'Wenn die WP-Website-Sprache keine Inhaltsprache ist: WooCommerce-Produktabfragen liefern auf allen Katalogblöcken null Ergebnisse; die Produktbild-Delegation schlägt fehl; alle sprachgefilterten Inhaltsabfragen brechen zusammen; der Sprachumschalter zeigt möglicherweise eine falsche Nicht-Inhalts-Sprache an. Wenn du eine rote Konfigurationswarnung oben im Router- oder System-Tab siehst, korrigiere zuerst die Sprache der Website.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE-Lokalisierung: Gerüst, Übersetzung und Korrektur von Links in Full Site Editing-Vorlagen und Vorlagenabschnitten direkt von diesem Tab aus.','Glossary Tab'=>'Glossar-Tab','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Markiere Begriffe, die nicht übersetzt werden sollen oder immer auf eine bestimmte Weise dargestellt werden müssen (z.B. Markennamen, Produktnamen, Akronyme). Glossar-Einschränkungen werden in jede KI-Übersetzungsanfrage für alle Funktionen eingebunden: Beitrag-Übersetzung, Meta-Beschreibung, Auszug und FSE-Vorlagenübersetzung.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Füge einen Begriff pro Zeile hinzu. Sowohl der Quellbegriff als auch die Zielübersetzung sind erforderlich. Das Sprachpaar bestimmt, für welche Übersetzungsaufträge die Einschränkung gilt.','SEO Tab'=>'SEO-Tab','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge ist eine vollständige mehrsprachige SEO-Lösung. Es ist kein zusätzliches SEO-Plugin oder Sitemap-Plugin erforderlich.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Was LF bietet: hreflang-Tags für jede konfigurierte Sprache, Open Graph- und Twitter Card-Tags mit og:locale und og:locale:alternate, Schema.org JSON-LD mit inLanguage-Annotationen und eine spezielle mehrsprachige Sitemap unter /lf-sitemap.xml mit xhtml:link Alternativ-Einträgen für alle Übersetzungsgruppen.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Die Sitemap wird automatisch in robots.txt angekündigt. Alle großen Suchmaschinen — Google, Bing, Yandex — entdecken sie aus robots.txt. Keine manuelle Einreichung erforderlich.','SEO plugins and conflict avoidance:'=>'SEO-Plugins und Konfliktvermeidung:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Wenn du Yoast SEO, Rank Math, All in One SEO oder SEOPress installiert hast, erkennt Lingua Forge sie und passt sich an, um doppelte Ausgaben zu vermeiden. Für hreflang übernimmt LF vollständig und unterdrückt die Ausgabe des Plugins, weil diese Plugins kein korrektes hreflang für eine mehrsprachige Routing-Konfiguration produzieren können. Für Open Graph fügt LF nur og:locale und og:locale:alternate hinzu — die mehrsprachigen Signale, die das Plugin nicht bereitstellen kann — und lässt das Basis-OG-Set beim Plugin. Für Schema.org deaktiviert LF seine eigene Ausgabe vollständig, um Konflikte bei JSON-LD-Grafiken zu vermeiden.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Der Reiter SEO → Kompatibilität zeigt den Live-Erkennungsstatus und erklärt genau, was LF in jedem Funktionsbereich tut.','SEO Scores'=>'SEO-Punkte','SEO Score System'=>'SEO-Punktesystem','Score computation'=>'Punktesystemberechnung','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Jeder Beitrag wird anhand von sechs regelbasierten Metriken bewertet: Titel, Meta-Beschreibung, Wortanzahl, Überschriftenstruktur, Bild-Alt-Abdeckung und interne Links. Zehn Punkte werden immer für die Lesezeit vergeben (nur informativ). Die restlichen 90 Punkte werden auf die anderen Metriken verteilt, mit Gewichten, die je nach Inhaltsprofil variieren (siehe unten).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Jede Metrik ergibt einen von vier Status: ok (volle Gewichtung), warn (50 % der Gewichtung), fail (0) oder info (0, keine Strafe). Eine Punktzahl ≥ 80 ist grün, 50–79 orange, unter 50 rot.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Regeln für die Bewertung des Titels (alle Profile): bei Leerheit fehlschlagen; bei weniger als 10 Zeichen warnen; bei nur einem Wort warnen; bei längerer Überschrift als das SERP-Limit (60 Zeichen für Blog, 70 für Produkt/Landing) warnen; bei mindestens 10 Zeichen, mindestens 2 Wörtern und innerhalb des SERP-Limits in Ordnung.','Content profiles and weights'=>'Inhaltsprofile und Gewichte','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profile passen Schwellenwerte und Gewichte an die Art des analysierten Inhalts an. Das Profil wird automatisch aufgelöst; du kannst es pro Analysevorgang im Dropdown-Menü für Profile überschreiben.','Blog / Editorial (default)'=>'Blog / Redaktion (Standard)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Titel 15 Punkte · Meta-Beschreibung 20 Punkte · Wortzahl 15 Punkte · Überschriften 20 Punkte · Bilder 10 Punkte · Links 10 Punkte. Titel SERP-Limit 60 Zeichen; Meta 120–210 Zeichen; Wortzahl-Warnung unter 300, Fehler unter 100; H2 erforderlich; interne Links erforderlich.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Automatisch erkannt für WooCommerce-Produkte. Titel 20 Punkte · Meta-Beschreibung 30 Punkte · Wortanzahl 15 Punkte · Überschriften 5 Punkte · Bilder 20 Punkte · Links 0 Punkte. Titel SERP-Limit 70 Zeichen; Wortzahl-Warnung unter 80, Fehler unter 40; H2 und interne Links optional.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Automatisch erkannt für die statische Startseite; kann manuell ausgewählt werden. Titel 20 Punkte · Meta-Beschreibung 30 Punkte · Wortanzahl 15 Punkte · Überschriften 10 Punkte · Bilder 15 Punkte · Links 0 Punkte. Titel SERP-Limit 70 Zeichen; Wortzahl-Warnung unter 150, Fehler unter 60; H2 und interne Links optional.','Heading structure rules'=>'Regeln für die Überschriftenstruktur','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Genau ein H1 ist erforderlich. Das H1 ist normalerweise der vom Theme gerenderte Beitragstitel — es wird, wenn möglich, von der live gerenderten Seite gelesen, andernfalls aus dem Beitrag-Inhalt.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Wenn das Blog-Profil ein H2 erfordert und keines gefunden wird, prüft der Analysator zuerst auf H3-Unterüberschriften, bevor eine Warnung ausgegeben wird. Akkordeon- und Details-Blöcke verwenden standardmäßig H3 für ihre Überschriften; diese H3s werden als gültige Struktur akzeptiert und ergeben ein OK-Ergebnis, keine Warnung.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Kurze Inhalte (3 Absätze oder weniger) werden niemals für fehlende Unterüberschriften bestraft, unabhängig vom Profil. Eine prägnante Seite profitiert nicht von einer erzwungenen Überschriftenstruktur.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Behandle H2 als H1-Äquivalent" (Einstellungen → SEO → Analyse): aktiviere dies, wenn dein Theme den Beitragstitel in einem H2 anstelle eines H1 rendert. Der Analysator hebt das erste H2 auf H1 an, damit die Punktzahl nicht falsch bestraft wird.','Score history and badges'=>'Punktverlauf und Abzeichen','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Jedes Mal, wenn ein Beitrag analysiert wird, wird die Punktzahl in den Beitrag-Meta gespeichert. Die Spalte "Sprache" in der Beitragsliste zeigt ein farbcodiertes "SEO N"-Abzeichen für jeden Beitrag, der mindestens einmal analysiert wurde. Wenn zwei Punktzahlen gespeichert sind, zeigt ein Delta-Indikator (↑N / ↓N) die Änderung seit dem letzten Lauf.','AI Usage & Cache Tab'=>'AI-Nutzung & Cache-Tab','Token usage'=>'Token-Nutzung','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Die Nutzungs-Tabelle zeigt den AI-Token-Verbrauch nach Funktion (Übersetzung, Meta-Beschreibung, Auszug, FSE-Vorlage, Batch-Analyse), Anbieter und Modell. Nutze die Datumsbereich-Buttons, um nach heute, letzten 7 Tagen, letzten 30 Tagen oder allem zu filtern.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Das tägliche Kontingent (konfiguriert in Verhalten → Limits) wird hier verfolgt. Wenn das Kontingent erreicht ist, werden AI-Aufrufe für den Rest des Tages ausgesetzt. Die Tabelle zeigt, wie viel des Kontingents verbraucht wurde.','Translation caching'=>'Übersetzungscaching','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge verwendet zwei unabhängige Caching-Schichten, um redundante AI-API-Aufrufe zu reduzieren:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Speichert rohe AI-Antworten, die nach Inhalts-Hash, Sprachpaar, Anbieter, Modell und Voreinstellung geordnet sind. Cache-Einträge werden automatisch invalidiert, wenn sich der Inhalt des Quellbeitrags ändert. Lösche einzelne Beiträge oder den gesamten Cache in diesem Tab.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Speichert die vollständige übersetzte Beitragsausgabe pro Inhalts-Hash. Opt-in (aktiviert im Verhalten). Beschleunigt wiederholte Übersetzungen unveränderter Inhalte. Lösche sie hier, wenn du eine frische AI-Analyse erzwingen möchtest, unabhängig davon, ob sich der Inhalt geändert hat.','Maintenance Tab'=>'Wartung-Tab','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Sprachüberschreibungen: Verwalte benutzerdefinierte .po/.mo-Überschreibungsdateien für die Lingua Forge UI-Strings. Verwende dies anstelle der direkten Bearbeitung der Plugin-Dateien — Überschreibungen überleben Updates.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: Aktiviere das Debug-Protokoll, um KI-Anfragen und API-Antworten in eine lokale Datei zu erfassen. Nach der Fehlerbehebung deaktivieren — der Debug-Modus schreibt bei jeder KI-Anfrage eine Datei.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Deinstallationsverhalten: Steuert, was beim Entfernen des Plugins gelöscht wird, unter Plugins → Installierte Plugins → Löschen. Plugin-Einstellungen und KI-Caches werden immer entfernt. Sprachzuweisungen, Übersetzungsbeziehungen, Meta-Beschreibungen, Glossar und Übersetzungs-Speicher bleiben standardmäßig erhalten, damit eine versehentliche Deinstallation oder Neuinstallation dort anknüpfen kann, wo sie aufgehört hat. Aktiviere "Inhalt-Daten bei Deinstallation löschen" nur, wenn du die mehrsprachige Unterstützung vollständig vom Server entfernen möchtest — dies ist nicht rückgängig zu machen.','System Tab'=>'System-Tab','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Nur-Lese-Diagnosen für die aktuelle Installation. Hier werden keine Einstellungen geändert — nutze es, um die Konfiguration zu überprüfen, Probleme zu erkennen und Informationen für Fehlerberichte zu sammeln.','Sections'=>'Abschnitte','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress- und PHP-Versionen; aktives Theme; URL-Struktur; WP-Seiten-Sprache und primäre Inhaltsprache. Ein rotes Symbol neben der WP-Seiten-Sprache bedeutet, dass sie keine der aktiven Inhaltssprachen ist — behebe das in Einstellungen → Allgemein, bevor du etwas anderes machst.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Aktiver Anbieter, konfigurierte Schlüssel, Modellstufen-Auswahl, Voreinstellungen und tägliches Kontingent.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Bestätigt, dass die Permalink-Struktur mit Lingua Forge Pfadrouting kompatibel ist. Einfache und nur numerische Strukturen werden nicht unterstützt.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Listet alle aktiven Drittanbieter-SEO-Plugins auf. Lingua Forge passt seine Ausgabe an, wenn diese vorhanden sind — siehe Einstellungen → SEO → Kompatibilität für die Aufschlüsselung pro Funktion.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce-Version, Speicher-Modus für Bestellungen (CPT / HPOS / gemeinsam) und eine Tabelle mit Übersetzungsabdeckung pro Sprache für die vier integrierten WC-Seiten (Shop, Warenkorb, Kasse, Mein Konto).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Listet Beitragstypen auf, die veröffentlichte Beiträge ohne _lf_lang-Meta-Wert haben. Beiträge ohne dieses Tag sind für alle Sprachfilter unsichtbar. Nutze die Reparieren-Schaltfläche, um sie mit der Quellsprache zu markieren, oder Exkludieren, um den Beitragstyp vollständig aus der Sprachrouting zu entfernen.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Zusammenfassung aller LF-eigenen Einträge in $wp_rewrite->extra_rules_top. Nützlich zur Diagnose von 404-Fehlern oder Routing-Konflikten nach Hinzufügen einer neuen Sprache.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Ein-Klick-Kopie einer einfachen Systemzusammenfassung, die alle oben genannten Abschnitte abdeckt. Füge dies in ein GitHub-Issue oder Support-Anfrage ein, damit die vollständige Umgebung auf einen Blick sichtbar ist.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Hast du einen Fehler oder unerwartetes Verhalten gefunden? Bitte öffne ein Issue auf GitHub — füge den Debug-Info-Block oben und eine kurze Beschreibung bei, was du erwartet hast vs. was passiert ist.','Open an issue →'=>'Öffne ein Issue →','Getting started'=>'Erste Schritte','Server setup (subdomain)'=>'Servereinrichtung (Subdomain)','Translation workflow'=>'Übersetzungsworkflow','Language switcher'=>'Sprachumschalter','WP-CLI reference'=>'WP-CLI Referenz','Integration API'=>'Integrations-API','Documentation'=>'Dokumentation','Report an issue on GitHub'=>'Melde ein Problem auf GitHub','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'WordPress KI-Client (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta-Beschreibung, Exzerpt-Generator','Translation, Content Generator'=>'Übersetzung, Inhaltserstellung','Testing…'=>'Wird getestet…','✓ Connection OK'=>'✓ Verbindung OK','✗ Failed:'=>'✗ Fehler: ','No response from provider — check the error log for details.'=>'Keine Antwort vom Anbieter — Überprüfe das Fehlerprotokoll für Details.','Network error — could not reach the WordPress AJAX endpoint.'=>'Netzwerkfehler — konnte die WordPress AJAX-Schnittstelle nicht erreichen.','Translating a real post with this model…'=>'Übersetzung eines echten Beitrags mit diesem Modell…','preset'=>'Vorgabe','Loading…'=>'Lädt…','Installing…'=>'Installiert…','✓ Language installed.'=>'✓ Sprache installiert.','✗ Error:'=>'✗ Fehler:','Creating…'=>'Wird erstellt…','✓ All templates created.'=>'✓ Alle Vorlagen erstellt.','Some templates could not be created.'=>'Einige Vorlagen konnten nicht erstellt werden.','Recreating…'=>'Wird neu erstellt…','✓ All templates recreated.'=>'✓ Alle Vorlagen neu erstellt.','Some templates could not be recreated.'=>'Einige Vorlagen konnten nicht neu erstellt werden.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Dies überschreibt diese Vorlage mit einer frischen Kopie aus dem aktiven Theme und verwirft alle im Site Editor vorgenommenen Anpassungen. Dies kann nicht rückgängig gemacht werden. Fortfahren?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dies überschreibt jede Vorlage mit einer frischen Kopie aus dem aktiven Theme und verwirft alle im Site Editor vorgenommenen Anpassungen. Dies kann nicht rückgängig gemacht werden. Fortfahren?','✓ All parts recreated.'=>'✓ Alle Teile neu erstellt.','Some parts could not be recreated.'=>'Einige Teile konnten nicht neu erstellt werden.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Dies überschreibt diesen Vorlagenteil mit einer frischen Kopie aus dem aktiven Theme und verwirft alle im Site Editor vorgenommenen Anpassungen. Dies kann nicht rückgängig gemacht werden. Fortfahren?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dies überschreibt jeden Vorlagenteil mit einer frischen Kopie aus dem aktiven Theme und verwirft alle im Site Editor vorgenommenen Anpassungen. Dies kann nicht rückgängig gemacht werden. Fortfahren?','✓ All parts created.'=>'✓ Alle Teile erstellt.','Some parts could not be created.'=>'Einige Teile konnten nicht erstellt werden.','✓ All translated.'=>'✓ Alle übersetzt.','Some translations failed.'=>'Einige Übersetzungen sind fehlgeschlagen.','Review carefully — links and slugs not updated.'=>'Überprüfe sorgfältig — Links und Slugs wurden nicht aktualisiert.','Fixing…'=>'Wird repariert…','✓ Links fixed.'=>'✓ Links repariert.','Some link fixes failed.'=>'Einige Link-Reparaturen sind fehlgeschlagen.','✓ Parts fixed.'=>'✓ Teile repariert.','Some part fixes failed.'=>'Einige Teile-Reparaturen sind fehlgeschlagen.','✓ Nav refs fixed.'=>'✓ Navigationsreferenzen repariert.','Some nav ref fixes failed.'=>'Einige Navigationsreferenz-Reparaturen sind fehlgeschlagen.','✓ Pattern translated.'=>'✓ Muster übersetzt.','Pattern translation failed.'=>'Musterübersetzung fehlgeschlagen.','Hide'=>'Verbergen','Re-create all templates'=>'Alle Vorlagen neu erstellen','Re-create all parts'=>'Alle Teile neu erstellen','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Dies führt Alle Vorlagen neu erstellen, Alle Teile neu erstellen, Alle übersetzen, Alle Teile reparieren und Alle Links reparieren für jede Ihrer {total} aktiven Sprachen nacheinander aus. Es überschreibt vorhandene Vorlagen und Teile mit frischen Kopien aus dem aktiven Theme (verwirft Site Editor-Anpassungen) und übersetzt Inhalte neu – nichts davon kann rückgängig gemacht werden. Alle übersetzen führt echte KI-API-Aufrufe für jede Vorlage und jeden Teil aus, was lange dauern kann und je nach Anbieter Kosten verursachen kann. Fortfahren?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Dies führt Alle Vorlagen neu erstellen, Alle übersetzen, Alle Teile reparieren und Alle Links reparieren für jede Ihrer {total} aktiven Sprachen nacheinander aus – Vorlagenteile (Header, Footer usw.) bleiben unberührt. Es überschreibt vorhandene Vorlagen mit frischen Kopien aus dem aktiven Theme (verwirft Site Editor-Anpassungen) und übersetzt Inhalte neu – nichts davon kann rückgängig gemacht werden. Alle übersetzen führt echte KI-API-Aufrufe für jede Vorlage aus, was lange dauern kann und je nach Anbieter Kosten verursachen kann. Fortfahren?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Dies führt Alle Teile neu erstellen (Header, Footer und jeden anderen Vorlagenteil) für jede Ihrer {total} aktiven Sprachen nacheinander aus. Es überschreibt vorhandene Vorlagenteile mit frischen Kopien aus dem aktiven Theme und verwirft alle im Site Editor vorgenommenen Anpassungen. Dies kann nicht rückgängig gemacht werden. Fortfahren?','Starting…'=>'Wird gestartet…','Processing {lang} ({index} of {total}) — {step}…'=>'Verarbeite {lang} ({index} von {total}) — {step}…','Cancelled.'=>'Abgebrochen.','{done} of {total} languages processed.'=>'{done} von {total} Sprachen verarbeitet.','⚠ Done with issues.'=>'⚠ Fertig mit Problemen.','✓ All {total} languages processed.'=>'✓ Alle {total} Sprachen verarbeitet.','Built-in preset instructions:'=>'Integrierte Voreinstellungen: ','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Keine integrierten Anweisungen — jede KI-Funktion verwendet ihre eigenen abgestimmten Standardwerte. Fülle das Feld für benutzerdefinierte Anweisungen unten aus, um eigene siteweite Regeln hinzuzufügen.','Modified'=>'Geändert','edit'=>'Bearbeiten','No published posts found for the selected filters.'=>'Keine veröffentlichten Beiträge für die ausgewählten Filter gefunden.','Just now'=>'Gerade eben','Score'=>'Punktzahl','Source title'=>'Quelltitel','Multilingual SEO overview'=>'Überblick über mehrsprachige SEO','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Punktzahlen sind ein Signal, kein Urteil. Einige Inhalte sind strukturell eingeschränkt — sehr kurze Seiten, Landing Pages mit wenig Text oder Seiten, deren Zweck Navigation ist, können von Natur aus niedriger punkten. Nutze diese Übersicht, um echte Paritätslücken zwischen den Sprachen zu erkennen, nicht um eine Zahl zu verfolgen.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Dies ist eine WooCommerce-Systemseite (Shop, Warenkorb, Kasse usw.). Ihr Inhalt wird von WooCommerce verwaltet — die Punktzahl spiegelt nur strukturelle Signale wider, nicht vom Nutzer bearbeitbare SEO-Inhalte.','Settings'=>'Einstellungen','You do not have permission to manage these settings.'=>'Du hast keine Berechtigung, diese Einstellungen zu verwalten.','Lingua Forge — Settings'=>'Lingua Forge — Einstellungen','Settings saved.'=>'Einstellungen gespeichert.','Save Settings'=>'Einstellungen speichern','Standard'=>'Standard','Technical / Scientific'=>'Technisch / Wissenschaftlich','Legal / Compliance'=>'Rechtlich / Compliance','Creative / Marketing'=>'Kreativ / Marketing','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — KI-Nutzungsstatistiken','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI Nutzungsstatistiken','Date'=>'Datum','Request count'=>'Anfragezahl','Full Article'=>'Vollständiger Artikel','Introduction only'=>'Nur Einführung','Structured Outline'=>'Strukturierte Gliederung','Generate Content'=>'Inhalt generieren','Hints'=>'Hinweise','Key points, ideas, or structure to build from…'=>'Wichtige Punkte, Ideen oder Strukturen, auf denen aufgebaut werden kann…','Tone'=>'Ton','Output'=>'Ausgabe','Generate Excerpt'=>'Auszug generieren','Generate Meta Description'=>'Meta-Beschreibung generieren','Translate Content'=>'Inhalt übersetzen','Mode'=>'Modus','Full post'=>'Vollständiger Beitrag','Translate chunk'=>'Abschnitt übersetzen','Target Language'=>'Zielsprache','Text to translate'=>'Zu übersetzender Text','Paste a footnote, sentence, or any snippet here…'=>'Füge hier eine Fußnote, einen Satz oder einen beliebigen Ausschnitt ein…','Also generate meta description'=>'Meta-Beschreibung ebenfalls generieren','Translated Labels'=>'Übersetzte Labels','Attribute label displayed in this language. Leave empty to use the default label.'=>'Attributbezeichnung in dieser Sprache angezeigt. Leer lassen, um die Standardbezeichnung zu verwenden.','Translate all labels (AI)'=>'Alle Labels übersetzen (KI)','Insufficient permissions.'=>'Unzureichende Berechtigungen.','All labels already translated.'=>'Alle Bezeichnungen sind bereits übersetzt.','%d label(s) translated.'=>'%d Bezeichnung(en) übersetzt.','Translation failed. Check the browser console.'=>'Übersetzung fehlgeschlagen. Überprüfe die Browser-Konsole.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Kann nicht auf Produkt %1$d schreiben: Es ist eine übersetzte Version (Sprache: %2$s)%3$s. Operative Daten (Preis, Lagerbestand, SKU, Maße) müssen beim Quellprodukt aktualisiert werden. Bestimme die Quellprodukt-ID über: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Übersetzte Namen','Name displayed in this language. Leave empty to use the source name.'=>'Name, der in dieser Sprache angezeigt wird. Leer lassen, um den Quellnamen zu verwenden.','Translate all tags (AI)'=>'Alle Tags übersetzen (KI)','Translate all categories (AI)'=>'Alle Kategorien übersetzen (KI)','Translate all %s terms (AI)'=>'Alle %s-Begriffe übersetzen (KI)','Translate all terms (AI)'=>'Alle Begriffe übersetzen (KI)','Invalid taxonomy.'=>'Ungültige Taxonomie.','No terms found.'=>'Keine Begriffe gefunden.','%d term(s) translated.'=>'%d Begriff(e) übersetzt.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d bereits übersetzt — <a href="#" class="lf-force-translate">erneut übersetzen</a>','%1$d translated, %2$d skipped.'=>'%1$d übersetzt, %2$d übersprungen.','Order placed in language: %s'=>'Bestellung aufgegeben in Sprache: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Ungültiger API-Schlüssel — überprüfe den eingegebenen Schlüssel in den AI-Anbieter-Einstellungen.','Payment required — your account has no remaining credits.'=>'Zahlung erforderlich — dein Konto hat keine verbleibenden Credits.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Zugriff verboten — dein Konto könnte gesperrt sein oder der Schlüssel hat nicht die erforderlichen Berechtigungen.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Rate-Limiting — zu viele Anfragen an den Anbieter gesendet; warte einen Moment und versuche es erneut.','Provider service temporarily unavailable — try again in a moment.'=>'Anbieter-Service vorübergehend nicht verfügbar — versuche es in einem Moment erneut.','Provider error (HTTP %1$d): %2$s'=>'Anbieterfehler (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Unerwarteter Anbieterfehler (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Kein API-Schlüssel konfiguriert — gib deinen Schlüssel in den AI-Anbieter-Einstellungen ein.','Network error — could not reach the provider: %s'=>'Netzwerkfehler — konnte den Anbieter nicht erreichen: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Keine Credits mehr — lade dein OpenAI-Konto unter platform.openai.com/account/billing auf.','WordPress AI Client requires WordPress 7.0 or later.'=>'WordPress KI-Client erfordert WordPress 7.0 oder später.','No user message found in the message array.'=>'Keine Benutzer-Nachricht im Nachrichtenarray gefunden.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Kein Text-Generierungsmodell verfügbar. Konfiguriere einen KI-Anbieter in Einstellungen → Connectors.','Too many AI requests. Please retry in %d seconds.'=>'Zu viele KI-Anfragen. Bitte versuche es in %d Sekunden erneut.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Tägliches KI-Kontingent erreicht (%1$d Anfragen). Setzt um %2$s UTC zurück.','View Lingua Forge details'=>'Details zu Lingua Forge anzeigen','View details'=>'Details anzeigen','Visit plugin site'=>'Plugin-Seite besuchen','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Lingua Forge Update blockiert: Download-Host "%s" ist nicht auf der Zulassungsliste.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Lingua Forge Update blockiert: SHA-256 des heruntergeladenen Pakets stimmt nicht mit dem Manifest überein. Die Datei könnte manipuliert worden sein.','Exclude from navigation menus'=>'Aus Navigationsmenüs ausschließen','Apply to all language versions'=>'Auf alle Sprachversionen anwenden','Lang'=>'Sprache','Also mirrored to: %s'=>'Auch gespiegelt nach: %s','Filter by language'=>'Nach Sprache filtern','All languages'=>'Alle Sprachen','Noindex (hide this language version from search engines)'=>'Noindex (verstecke diese Sprachversion vor Suchmaschinen)','%d language not yet linked'=>'%d Sprache noch nicht verknüpft' . "\0" . '%d Sprachen noch nicht verknüpft','This is the source page. Footnotes are edited directly in the block editor.'=>'Dies ist die Quellseite. Fußnoten werden direkt im Blockeditor bearbeitet.','No source page linked yet.'=>'Noch keine Quellseite verknüpft.','The source page has no footnotes.'=>'Die Quellseite hat keine Fußnoten.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Diese Fußnoten stammen von der Quellseite und werden hier nur zur Referenz angezeigt. Füge sie mit dem Blockeditor auf dieser Seite hinzu.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalisierte Vorlage(n) aus dem &#8220;%2$s&#8221;-Theme sind in der Datenbank erhalten, sind aber momentan inaktiv. Sie werden wieder aktiv, wenn du dieses Theme erneut aktivierst. Um deine Übersetzungen auf das neue Theme zu übertragen, generiere sie erneut über <strong>Einstellungen → Lingua Forge → Router → FSE-Scaffold</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Beiträge werden auf fehlende oder nicht synchronisierte Beitragsbilder gescannt…','Re-scanning…'=>'Neu scannen…','Scan failed: '=>'Scan fehlgeschlagen: ','unknown error'=>'Unbekannter Fehler','Scan request failed. Please try again.'=>'Scan-Anfrage fehlgeschlagen. Bitte versuche es erneut.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Keine <strong>{lang}</strong>-Beiträge gefunden. Stelle sicher, dass alle übersetzten Beiträge ihre Sprach-Meta auf <strong>{lang}</strong> gesetzt haben.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Alle <strong>{lang}</strong> Featured Images sind bereits mit ihrem Quellbeitrag synchronisiert. Gescannte <strong>{scanned}</strong> Beitrag(e).','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Es wurden <strong>{n}</strong> Beitrag/Beiträge gefunden, die ihre Quell-Beitragsbild vermissen oder nicht synchron sind, von <strong>{scanned}</strong> gescannten für <strong>{lang}</strong>.','Post'=>'Beitrag','Current'=>'Derzeit','Source (EN)'=>'Quelle (EN)','None'=>'Keine','Copy from source'=>'Aus Quelle kopieren','Copying…'=>'Kopieren…','✅ Copied'=>'✅ Kopiert','❌ Failed'=>'❌ Fehlgeschlagen','Done — {done} of {total} post(s) fixed.'=>'Fertig — {done} von {total} Beiträgen repariert.','Fixing {n} / {total}…'=>'Repariere {n} / {total}…','Fix Featured Images'=>'Featured Images reparieren','Featured Image Fixer'=>'Featured Image Fixer','Fix All'=>'Alle reparieren','Re-scan'=>'Neu scannen','Scanning posts for broken language links…'=>'Suche nach defekten Sprachlinks in Beiträgen…','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Keine defekten Links oder Template-Fehler für <strong>{lang}</strong> gefunden. Es wurden <strong>{scanned}</strong> Beitrag(e) und Seite(n) gescannt — alle Prüfungen bestanden. Links zu Template-Teilen (Header, Footer, Sidebar) sind hier nicht enthalten — benutze die Schaltfläche "Template-Teile reparieren", um diese separat zu prüfen.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatisch reparierbare Link(s)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> Link(s) zur manuellen Überprüfung','and'=>'und','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Gefunden {parts} in <strong>{total}</strong> von <strong>{scanned}</strong> gescannten Beiträgen für <strong>{lang}</strong>.','link(s)'=>'Link(s)','Fix'=>'Reparieren','✅ Fixed ({n})'=>'✅ Behoben ({n})','⚠ No changes — re-scan?'=>'⚠ Keine Änderungen — erneut scannen?','⚠ No changes'=>'⚠ Keine Änderungen','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hatten keine ersetzbaren Links — erneut scannen, um zu untersuchen)','URL could not be mapped to a post — check the link target exists'=>'URL konnte keinem Beitrag zugeordnet werden — überprüfe, ob das Ziel existiert','No {lang} translation registered (TRID missing)'=>'Keine {lang}-Übersetzung registriert (TRID fehlt)','Translation found but permalink could not be generated'=>'Übersetzung gefunden, aber Permalink konnte nicht generiert werden','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> veralteter Pfad(e)','📍 Stale path (page moved)'=>'📍 Veralteter Pfad (Seite verschoben)','{n} stale path(s)'=>'{n} veralteter Pfad(e)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> Template-Problem(e)','📄 Wrong template'=>'📄 Falsches Template','Expected: {expected}'=>'Erwartet: {expected}','Current: {current}'=>'Aktuell: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Template "{expected}" existiert nicht — erstelle es zuerst im Site Editor.','Fix Template'=>'Template reparieren','✅ Template fixed'=>'✅ Template repariert','Internal Link Fixer'=>'Interner Link-Fehlerbeheber','Language Switcher'=>'Sprachumschalter','Displays the Lingua Forge language switcher.'=>'Zeigt den Lingua Forge Sprachumschalter an.','Display'=>'Anzeige','Language label'=>'Sprachlabel','Icon only'=>'Nur Icon','Icon + label'=>'Icon + Label','Dropdown direction'=>'Dropdown-Richtung','Down'=>'Nach unten','Up'=>'Nach oben','Select language'=>'Sprache auswählen','Close language panel'=>'Sprachpanel schließen','You do not have permission to read this post.'=>'Du hast keine Berechtigung, diesen Beitrag zu lesen.','Limit results to pages in the given Lingua Forge language code.'=>'Ergebnisse auf Seiten im angegebenen Lingua Forge Sprachcode beschränken.','Link copied'=>'Link kopiert','Copy failed — please copy the URL manually.'=>'Kopieren fehlgeschlagen — bitte kopiere die URL manuell.','Trash + Siblings'=>'Papierkorb + Geschwister','Move to Trash (incl. translations)'=>'In Papierkorb verschieben (inkl. Übersetzungen)','Trashed %d post (including translations).'=>'%d Beitrag in Papierkorb verschoben (inkl. Übersetzungen).' . "\0" . '%d Beiträge in Papierkorb verschoben (inkl. Übersetzungen).','%d post was skipped (no permission or protected).'=>'%d Beitrag wurde übersprungen (keine Berechtigung oder geschützt).' . "\0" . '%d Beiträge wurden übersprungen (keine Berechtigung oder geschützt).','Meta Description'=>'Meta-Beschreibung','Using custom meta description.'=>'Verwendung einer benutzerdefinierten Meta-Beschreibung.','Prefilled from excerpt. Edit to override.'=>'Vordefiniert aus Auszug. Bearbeite, um zu überschreiben.','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Strebe 120–160 Zeichen an. Leer lassen, um den Auszug-Fallback zu verwenden.','Generated Content'=>'Generierter Inhalt','Generated meta description'=>'Generierte Meta-Beschreibung','Refine further:'=>'Weiter verfeinern:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Anweisungen hinzufügen, um den Entwurf zu verbessern — z.B. kürzer machen, einen Abschlussabschnitt hinzufügen, einen formelleren Stil verwenden, eine FAQ-Block einfügen…','↺ Refine'=>'↺ Verfeinern','Copy markup'=>'Markup kopieren','Apply to Editor'=>'Auf Editor anwenden','Copied ✓'=>'Kopiert ✓','Applying…'=>'Wird angewendet…','Applied ✓'=>'Angewandt ✓','Refining…'=>'Verfeinere…','Refinement failed — please try again.'=>'Verfeinerung fehlgeschlagen — bitte versuche es erneut.','Refinement'=>'Verfeinerung','✓ Refined — review the updated draft above.'=>'✓ Verfeinert — überprüfe den aktualisierten Entwurf oben.','Request failed — please try again.'=>'Anfrage fehlgeschlagen — bitte versuche es erneut.','Review translation before applying'=>'Überprüfung der Übersetzung vor dem Anwenden','Current title'=>'Aktueller Titel','Translated title'=>'Übersetzter Titel','Current content (will be overwritten)'=>'Aktueller Inhalt (wird überschrieben)','Translated content'=>'Übersetzter Inhalt','Footnotes payload (advanced)'=>'Fußnoten-Payload (fortgeschritten)','Saved to the meta description field when you apply.'=>'Beim Anwenden im Meta-Beschreibungsfeld gespeichert.','Apply translation'=>'Übersetzung anwenden','The editor did not accept the content — please try again.'=>'Der Editor hat den Inhalt nicht akzeptiert — bitte versuche es erneut.','Save the post to persist changes.'=>'Der Beitrag wird gespeichert, um Änderungen zu sichern.','Apply failed — please try again.'=>'Anwendung fehlgeschlagen — bitte versuche es erneut.','↺ Refreshing…'=>'↺ Aktualisieren…','Copy'=>'Kopieren','Apply to Meta Description'=>'Auf Meta-Beschreibung anwenden','Generating…'=>'Erzeuge…','Generation failed.'=>'Erstellung fehlgeschlagen.','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Inhalt erstellt — siehe die Überlagerung, um zu überprüfen, zu verfeinern und anzuwenden.','cached'=>'zwischengespeichert','Translated to:'=>'Übersetzt nach:','tone'=>'Ton','Content generated'=>'Inhalt erstellt','Content ready'=>'Inhalt fertig','footnote(s) translated — applied together with content.'=>'Fußnoten übersetzt — zusammen mit dem Inhalt angewendet.','Chunk translated to:'=>'Abschnitt übersetzt zu:','Chunk translated'=>'Abschnitt übersetzt','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Kopiere das Ergebnis und füge es bei Bedarf ein (z.B. direkt in das Fußnotefeld).','chars'=>'Zeichen','✓ Good length'=>'✓ Gutes Format','⚠ Borderline'=>'⚠ Grenzwertig','✗ Too short'=>'✗ Zu kurz','✗ Too long'=>'✗ Zu lang','Target: 140–160 chars for optimal SERP display'=>'Ziel: 140–160 Zeichen für optimale SERP-Anzeige','SEO character-count info'=>'SEO-Zeichenzählinfo','↺ Refresh'=>'↺ Aktualisieren','Re-generates and updates the cached result.'=>'Erzeugt und aktualisiert das zwischengespeicherte Ergebnis.','← Back'=>'← Zurück','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Füge Anweisungen hinzu, um den Entwurf zu verbessern — z.B. kürzer machen, einen Abschlussabschnitt hinzufügen, einen formelleren Stil verwenden…','Improve writing'=>'Schreiben verbessern','Make formal'=>'Formell machen','Make casual'=>'Umgangssprachlich machen','Make concise'=>'Kurz und bündig machen','Expand'=>'Erweitern','Bulletize (•-prefixed)'=>'Aufzählung (•-Präfix)','Lead paragraph (≤60 w)'=>'Einleitung (≤60 Wörter)','Mark citations needed'=>'Zitate als notwendig markieren','Plain language'=>'Einfache Sprache','Translate / Revise'=>'Übersetzen / Überarbeiten','Translate / Revise block'=>'Block übersetzen / überarbeiten','Revision'=>'Überarbeitung','Footnotes'=>'Fußnoten','Block Content'=>'Blockinhalt','Revision Type'=>'Überarbeitungsart','Revise'=>'Überarbeiten','Footnote Content'=>'Fußnoteninhalte','Apply to Block'=>'Auf Block anwenden','Instructions (optional)'=>'Anweisungen (optional)','Extra guidance — tone, style, constraints, target audience…'=>'Zusätzliche Hinweise — Ton, Stil, Einschränkungen, Zielgruppe…','Extra guidance — tone, style, constraints…'=>'Zusätzliche Hinweise — Ton, Stil, Einschränkungen…','↑ Detected from current post'=>'↑ Erkannt vom aktuellen Beitrag','Processing…'=>'Verarbeite…','Failed. Please try again.'=>'Fehlgeschlagen. Bitte versuche es erneut.','Request failed. Check your connection.'=>'Anfrage fehlgeschlagen. Überprüfe deine Verbindung.','Apply to Footnote'=>'Auf Fußnote anwenden','Quick Translate'=>'Schnelle Übersetzung','Paste text, or select text in the editor first…'=>'Füge Text ein oder wähle zuerst Text im Editor aus…','Clear input'=>'Eingabe löschen','Clear'=>'Löschen','Instructions / key points'=>'Anweisungen / Schlüsselpunkte','Describe what to write — topic, key points, structure…'=>'Beschreibe, was geschrieben werden soll — Thema, Schlüsselpunkte, Struktur…','Language (optional)'=>'Sprache (optional)','— auto-detect —'=>'— automatisches Erkennen —','Generate'=>'Generieren','Clear hints'=>'Hinweise löschen','Clear All'=>'Alles löschen','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Weiter verfeinern — z.B. "kürzer machen" oder "formelleren Ton verwenden"…','Please enter some text first…'=>'Bitte gib zuerst einen Text ein…','Please enter some instructions first…'=>'Bitte gib zuerst Anweisungen ein…','Request failed. Please try again.'=>'Anfrage fehlgeschlagen. Bitte versuche es erneut.','Tone:'=>'Ton:','Language:'=>'Sprache:','Done'=>'Fertig','Lingua Forge AI Tools'=>'Lingua Forge KI-Tools','Close popover'=>'Popover schließen','Paste text, or select text on the page first…'=>'Füge Text ein oder wähle zuerst Text auf der Seite aus…','Result will appear here…'=>'Das Ergebnis erscheint hier…','↺ Re-translate'=>'↺ Erneut übersetzen','Notice settings'=>'Hinweis-Einstellungen','Notice message'=>'Hinweisnachricht','Shown when no translation exists for the visitor\'s language.'=>'Wird angezeigt, wenn keine Übersetzung für die Sprache des Besuchers vorhanden ist.','Show home link'=>'Startseite-Link anzeigen','Adds a link to the home page so visitors can browse in their language.'=>'Fügt einen Link zur Startseite hinzu, damit Besucher in ihrer Sprache browsen können.','Home link text'=>'Startseiten-Link-Text','block titleMissing Translation Notice'=>'Hinweis bei fehlender Übersetzung','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Zeigt eine höfliche Mitteilung, wenn die aktuelle Seite in ihrer Originalsprache angezeigt wird, weil keine Übersetzung für die Sprache des Besuchers vorhanden ist. Gesteuert durch das LINGUAFORGE_LANG_FALLBACK_ACTIVE Signal des Lingua Forge Routers — gibt nichts aus, wenn eine Übersetzung für die Anfrage-Sprache existiert.','block keywordlanguage'=>'Sprache','block keywordtranslation'=>'Übersetzung','block keywordfallback'=>'Fallback','block keywordi18n'=>'i18n','block keywordlinguaforge'=>'linguaforge']];